/** True on chapter reader: defer heavy verse-breakdown stack until idle so LCP is not contended. */
function tdbIsChapterReaderPage() {
  if (typeof document === 'undefined' || !document) return false;
  try {
    if (document.getElementById('reader-book')) return true;
    if (document.getElementById('chapter-reader')) return true;
  } catch (_) {}
  return false;
}

/** True on /verse (Verse of the Day) — same idle breakdown deferral as the chapter reader. */
function tdbIsVerseOfDayPage() {
  if (typeof document === 'undefined' || !document) return false;
  try {
    if (document.body && document.body.classList.contains('tdb-verse-page')) return true;
    var p = typeof location !== 'undefined' && location.pathname ? String(location.pathname) : '';
    if (/\/verse\.html$/i.test(p)) return true;
    if (p === '/verse' || p === '/verse/') return true;
  } catch (_) {}
  return false;
}

/** True on the English homepage (Phase 6: defer heavy study/breakdown bundles like reader + verse of the day). */
function tdbIsHomePage() {
  if (typeof document === 'undefined' || !document) return false;
  try {
    if (document.body && (document.body.classList.contains('home') || document.body.getAttribute('data-tdb-page') === 'home')) {
      return true;
    }
    var p = typeof location !== 'undefined' && location.pathname ? String(location.pathname) : '';
    if (p === '/' || p === '/index.html') return true;
  } catch (_) {}
  return false;
}

