/** One consistent “Try again” for pages that use .tdb-soft-retry-btn (reload). CSP-safe — no inline handlers. */
function wireTdbSoftRetry() {
  if (typeof window === 'undefined' || window.__tdbSoftRetryWired) return;
  window.__tdbSoftRetryWired = true;
  document.addEventListener('click', function (e) {
    var btn = e.target && e.target.closest && e.target.closest('.tdb-soft-retry-btn');
    if (!btn) return;
    e.preventDefault();
    try {
      location.reload();
    } catch (_) {}
  });
}

function wireHashLinkFallbacks() {
  if (window.__tdbHashLinkFallbacksWired) return;
  window.__tdbHashLinkFallbacksWired = true;
  document.addEventListener('click', function (event) {
    var clicked = event.target;
    var link = clicked && clicked.closest ? clicked.closest('a[href="#"]') : null;
    if (!link || event.defaultPrevented) return;
    if (link.classList && link.classList.contains('cross-ref-link')) return;
    if (link.hasAttribute('data-ref') || link.hasAttribute('data-topic')) return;

    var id = String(link.id || '');
    if (id === 'sidebar-toggle') {
      event.preventDefault();
      if (document.body && document.body.classList) document.body.classList.toggle('sidebar-open');
      return;
    }

    if (id === 'sidebar-family-armor-stories' || id === 'toolbox-family-armor') {
      event.preventDefault();
      var armorBtn = document.getElementById('family-armor-stories-btn');
      if (armorBtn && typeof armorBtn.click === 'function') armorBtn.click();
      else window.location.href = '/#main-content';
      return;
    }

    if (id === 'toolbox-add-household') {
      event.preventDefault();
      var familyBtn = document.getElementById('add-family-btn');
      if (familyBtn && typeof familyBtn.click === 'function') familyBtn.click();
      else window.location.href = '/#main-content';
      return;
    }

    event.preventDefault();
    var main = document.getElementById('main-content') || document.querySelector('main');
    if (main && typeof main.scrollIntoView === 'function') main.scrollIntoView({ behavior: 'smooth', block: 'start' });
    else window.location.href = '/#main-content';
  });
}

function emitEasterEgg(eggId, payload) {
  try {
    if (window.TDBEasterEggs && typeof window.TDBEasterEggs.trigger === 'function') {
      window.TDBEasterEggs.trigger(eggId, payload || {});
      return;
    }
    if (!Array.isArray(window.__tdbEggQueue)) window.__tdbEggQueue = [];
    if (window.__tdbEggQueue.length > 40) window.__tdbEggQueue.shift();
    window.__tdbEggQueue.push({ id: eggId, payload: payload || {}, t: Date.now() });
  } catch (e) {}
}
window.__tdbEmitEasterEgg = emitEasterEgg;

(function initBibleLoopLibraryAutoRelease() {
  var grid = document.getElementById('loop-grid');
  if (!grid) return;

  /** Per-loop PNGs at /assets/loops/{id}.png are optional; use site asset until present (avoids 404s on /kids/corner, etc.). */
  var LOOP_THUMB_PLACEHOLDER = '/logo-shield-600.png';

  var START_DATE_MS = new Date('2026-03-01').getTime();
  var WEEK_MS = 7 * 24 * 60 * 60 * 1000;
  var STORAGE_KEY = 'tdb_loop_library_state_v2';
  /* Bump ?v= when loops.json shape/media URLs change so CDN/browsers skip stale JSON. */
  var LOOPS_URL = '/loops.json?v=20260524readquiz';
  var LOOPS_CACHE_KEY = 'tdb_loops_json_cache_v85';
  var MAX_WEEK = 12;
  var STAR_GOAL = 12;
  /* Fallback until loops.json loads; then synced to catalog length (roadmap cards). */
  var TOTAL_LOOPS = 233;
  /* Google Form: set in loop-feedback-config.js (edit that file when ready) or leave null for mailto fallback */
  var LOOP_FEEDBACK_FORM = (typeof window !== 'undefined' && window.LOOP_FEEDBACK_FORM) || null;

  var progressText = document.getElementById('loop-progress-text');
  var progressFill = document.getElementById('loop-progress-fill');
  var progressMeter = document.querySelector('.loop-progress-meter');
  var weeklyStatus = document.getElementById('loop-weekly-status');
  var unlockStatus = document.getElementById('loop-unlock-status');
  var toast = document.getElementById('loop-toast');

  var modal = document.createElement('div');
  modal.className = 'loop-modal is-hidden';
  modal.setAttribute('role', 'dialog');
  modal.setAttribute('aria-modal', 'true');
  modal.setAttribute('aria-label', 'Bible loop fullscreen player');

  var modalInner = document.createElement('div');
  modalInner.className = 'loop-modal-inner';
  var modalHeader = document.createElement('div');
  modalHeader.className = 'modal-header';
  var modalClose = document.createElement('button');
  modalClose.type = 'button';
  modalClose.className = 'loop-modal-close';
  modalClose.textContent = 'Close';
  modalClose.setAttribute('aria-label', 'Close full screen player');
  var modalTitle = document.createElement('h2');
  modalTitle.className = 'loop-modal-title';
  var gentleReturnRow = document.createElement('div');
  gentleReturnRow.className = 'gentle-return-row';
  var gentleReturnLink = document.createElement('a');
  gentleReturnLink.className = 'gentle-return-btn';
  gentleReturnLink.href = '#';
  gentleReturnLink.textContent = 'Back to this gentle story';
  var modalVideo = document.createElement('video');
  modalVideo.id = 'loop-modal-video';
  modalVideo.setAttribute('muted', '');
  modalVideo.setAttribute('playsinline', '');
  modalVideo.setAttribute('preload', 'none');
  var modalActions = document.createElement('div');
  modalActions.className = 'loop-modal-actions';
  var replayBtn = document.createElement('button');
  replayBtn.type = 'button';
  replayBtn.className = 'btn loop-btn-primary';
  replayBtn.textContent = 'Watch again?';
  var nextBtn = document.createElement('button');
  nextBtn.type = 'button';
  nextBtn.className = 'btn loop-btn-secondary is-hidden';
  nextBtn.textContent = 'Watch next?';
  var modalAudioWrap = document.createElement('div');
  modalAudioWrap.className = 'loop-modal-audio-wrap is-hidden';
  var modalAudioLabel = document.createElement('p');
  modalAudioLabel.className = 'loop-modal-audio-label';
  var modalAudioEl = document.createElement('audio');
  modalAudioEl.controls = true;
  modalAudioEl.preload = 'none';
  modalAudioEl.className = 'loop-modal-audio';
  modalAudioWrap.appendChild(modalAudioLabel);
  modalAudioWrap.appendChild(modalAudioEl);
  var modalHelper = document.createElement('p');
  modalHelper.className = 'section-note';

  modalActions.appendChild(replayBtn);
  modalActions.appendChild(nextBtn);
  gentleReturnRow.appendChild(gentleReturnLink);
  modalHeader.appendChild(modalClose);
  modalHeader.appendChild(modalTitle);
  modalInner.appendChild(modalHeader);
  modalInner.appendChild(gentleReturnRow);
  modalInner.appendChild(modalVideo);
  modalInner.appendChild(modalAudioWrap);
  modalInner.appendChild(modalActions);
  modalInner.appendChild(modalHelper);
  modal.appendChild(modalInner);
  document.body.appendChild(modal);

  modalVideo.addEventListener('error', function () {
    try {
      modalHelper.textContent = 'This loop video is not on the server yet. The poster stays visible until the file is uploaded.';
    } catch (_) {}
  });
  modalAudioEl.addEventListener('error', function () {
    try {
      modalAudioLabel.textContent = 'Verse audio is not available for this clip yet. The verse on the page is still here.';
    } catch (_) {}
  });

  var state = readState();
  var allLoops = [];
  var unlockedLoops = [];
  var currentLoop = null;
  var activeLoopFilter = 'all';
  var gentleLoopBridge = {
    active: false,
    primed: false,
    storyKey: '',
    storyTitle: '',
    storyRef: '',
    refStem: '',
    titleTokens: [],
    nextStoryKey: '',
    suggestedFilter: 'all'
  };

  try {
    var gentleParams = new URLSearchParams(location.search || '');
    gentleLoopBridge.storyKey = String(gentleParams.get('gentleStory') || '').trim();
    gentleLoopBridge.storyTitle = String(gentleParams.get('gentleTitle') || '').trim();
    gentleLoopBridge.storyRef = String(gentleParams.get('gentleRef') || '').trim();
    gentleLoopBridge.active = gentleParams.get('gentle') === '1' && (!!gentleLoopBridge.storyKey || !!gentleLoopBridge.storyTitle);
  } catch (e) {}

  function getGentleJourneyApi() {
    return (typeof window !== 'undefined' && window.TDB_GENTLE_JOURNEY) || null;
  }

  function refreshGentleLoopBridgeNextKey() {
    var api = getGentleJourneyApi();
    if (gentleLoopBridge.active && api && typeof api.hasKey === 'function' && api.hasKey(gentleLoopBridge.storyKey)) {
      gentleLoopBridge.nextStoryKey = api.getNextKey(gentleLoopBridge.storyKey) || '';
    }
    return gentleLoopBridge.nextStoryKey;
  }

  function loopTitleLower(loop) {
    return String(loop && loop.title ? loop.title : '').toLowerCase();
  }

  function normalizeGentleText(value) {
    return String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  }

  function getGentleRefStem(ref) {
    var safe = String(ref || '').trim();
    var match = safe.match(/^((?:[1-3]\s+)?[A-Za-z]+(?:\s+[A-Za-z]+)?)\s+(\d+)/);
    if (!match) return '';
    return (match[1] + ' ' + match[2]).toLowerCase();
  }

  function getGentleTitleTokens(value) {
    return normalizeGentleText(value).split(/\s+/).filter(function (token) {
      return token && token.length > 2 && !/^(the|and|with|from|into|this|that|story|jesus)$/.test(token);
    });
  }

  function getGentleFilterSuggestion(title, ref) {
    var hay = normalizeGentleText(String(title || '') + ' ' + String(ref || ''));
    if (/jesus|matthew|mark|luke|john|samaritan|prodigal|lost sheep|emmaus|cana|well/.test(hay)) return 'jesus';
    if (/david|daniel|esther|gideon|jericho|moses|jonah|samson|joshua|deborah|elijah|paul/.test(hay)) return 'brave';
    if (/noah|shepherd|children|lazarus|widow|hannah|ruth|blind|leper|storm/.test(hay)) return 'comfort';
    return 'all';
  }

  gentleLoopBridge.refStem = getGentleRefStem(gentleLoopBridge.storyRef);
  gentleLoopBridge.titleTokens = getGentleTitleTokens(gentleLoopBridge.storyTitle);
  gentleLoopBridge.suggestedFilter = getGentleFilterSuggestion(gentleLoopBridge.storyTitle, gentleLoopBridge.storyRef);
  if (gentleLoopBridge.active && activeLoopFilter === 'all' && gentleLoopBridge.suggestedFilter !== 'all') {
    activeLoopFilter = gentleLoopBridge.suggestedFilter;
  }

  function getGentleNextStoryHref() {
    if (!gentleLoopBridge.nextStoryKey) refreshGentleLoopBridgeNextKey();
    if (!gentleLoopBridge.nextStoryKey) return '';
    return '/kids/corner.html?story=' + encodeURIComponent(gentleLoopBridge.nextStoryKey) + '&gentle=1';
  }

  function getGentleReturnHref() {
    var nextHref = getGentleNextStoryHref();
    if (nextHref) return nextHref;
    if (gentleLoopBridge.storyKey) {
      return '/kids/corner.html?story=' + encodeURIComponent(gentleLoopBridge.storyKey) + '&gentle=1';
    }
    return '';
  }

  function handleLoopNextAction() {
    var gentleReturnHref = getGentleReturnHref();
    if (gentleLoopBridge.active && gentleReturnHref) {
      location.href = gentleReturnHref;
      return;
    }
    playRandomUnlocked();
  }

  function scoreGentleLoopMatch(loop) {
    if (!gentleLoopBridge.active || !loop) return -1;
    var sk = String(gentleLoopBridge.storyKey || '').trim();
    var lk = String(loop.libraryKey || '').trim();
    if (sk && lk && sk === lk) return 100;
    var score = 0;
    var loopTitle = normalizeGentleText(loop.title);
    var loopRefStem = getGentleRefStem(loop.ref);
    if (gentleLoopBridge.refStem && loopRefStem && gentleLoopBridge.refStem === loopRefStem) score += 6;
    for (var i = 0; i < gentleLoopBridge.titleTokens.length; i++) {
      if (loopTitle.indexOf(gentleLoopBridge.titleTokens[i]) !== -1) score += 2;
    }
    if (gentleLoopBridge.suggestedFilter !== 'all' && loopMatchesFilter(loop, gentleLoopBridge.suggestedFilter)) score += 1;
    return score;
  }

  function findGentleLoopCandidate(list) {
    var best = null;
    var bestScore = -1;
    var pool = Array.isArray(list) ? list : [];
    for (var i = 0; i < pool.length; i++) {
      var score = scoreGentleLoopMatch(pool[i]);
      if (score > bestScore) {
        best = pool[i];
        bestScore = score;
      }
    }
    return bestScore >= 4 ? best : null;
  }

  function maybePrimeGentleLoopBridge() {
    if (!gentleLoopBridge.active || gentleLoopBridge.primed || !allLoops.length) return;
    gentleLoopBridge.primed = true;
    var candidate = findGentleLoopCandidate(unlockedLoops);
    if (candidate) {
      if (weeklyStatus) weeklyStatus.textContent = 'Gentle Journey brought you here from "' + gentleLoopBridge.storyTitle + '". This matching loop is ready now.';
      openModal(candidate);
      return;
    }
    if (weeklyStatus) weeklyStatus.textContent = 'Gentle Journey brought you here from "' + gentleLoopBridge.storyTitle + '". No exact loop is ready yet, so here are nearby short replays.';
    if (gentleLoopBridge.suggestedFilter !== 'all') {
      activeLoopFilter = gentleLoopBridge.suggestedFilter;
      renderGrid();
    }
  }

  function loopMatchesFilter(loop, filterName) {
    var name = String(filterName || 'all').toLowerCase();
    if (!loop || name === 'all') return true;
    var title = loopTitleLower(loop);
    if (name === 'starter') return Number(loop.week) === 0;
    if (name === 'comfort') {
      return /noah|jesus calms|good shepherd|lost sheep|jesus blesses|baby moses|jairus|lazarus|widow|hannah|ruth|elijah fed by ravens|heals the leper|heals the blind|centurion/.test(title);
    }
    if (name === 'brave') {
      return /david|daniel|esther|gideon|jericho|moses|jonah|samson|shadrach|abednego|joshua|deborah|elijah|paul/.test(title);
    }
    if (name === 'jesus') {
      return /jesus|samaritan|prodigal|lost sheep|mustard|sower|talents|widow|emmaus|baptized|empty tomb|shepherd|cana/.test(title);
    }
    return true;
  }

  function getVisibleLoops() {
    return unlockedLoops.filter(function (loop) {
      return loopMatchesFilter(loop, activeLoopFilter);
    });
  }

  function describeLoopFilter(filterName, count) {
    if (filterName === 'starter') return 'Showing the Starter 12 loops for first visits and quick wins.';
    if (filterName === 'comfort') return 'Showing comfort loops for worried, sad, or bedtime moments.';
    if (filterName === 'brave') return 'Showing brave loops for courage, standing firm, and trusting God.';
    if (filterName === 'jesus') return 'Showing Jesus-centered loops for His care, teaching, and miracles.';
    return 'Showing every unlocked loop on this device' + (count ? ' (' + count + ')' : '') + '.';
  }

  function syncLoopFilterUi(count) {
    var chips = document.querySelectorAll('.loop-filter-chip[data-loop-filter]');
    chips.forEach(function (chip) {
      chip.classList.toggle('is-active', String(chip.getAttribute('data-loop-filter') || '') === activeLoopFilter);
    });
    var status = document.getElementById('loop-filter-status');
    if (status) status.textContent = describeLoopFilter(activeLoopFilter, count);
  }

  function wireLoopFilters() {
    var chips = document.querySelectorAll('.loop-filter-chip[data-loop-filter]');
    if (!chips || !chips.length) return;
    chips.forEach(function (chip) {
      chip.addEventListener('click', function () {
        activeLoopFilter = String(chip.getAttribute('data-loop-filter') || 'all').trim() || 'all';
        renderGrid();
      });
    });
  }

  function readState() {
    var fallback = { starredIds: [], watchCounts: {}, sundayRefreshTag: '' };
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return fallback;
      var parsed = JSON.parse(raw);
      if (!parsed || typeof parsed !== 'object') return fallback;
      return {
        starredIds: Array.isArray(parsed.starredIds) ? parsed.starredIds.map(Number) : [],
        watchCounts: parsed.watchCounts && typeof parsed.watchCounts === 'object' ? parsed.watchCounts : {},
        sundayRefreshTag: typeof parsed.sundayRefreshTag === 'string' ? parsed.sundayRefreshTag : ''
      };
    } catch (e) {
      return fallback;
    }
  }

  var selectedKidId = null;

  function writeState() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); } catch (e) {}
    if (selectedKidId && window.__tdbSupabaseClient) {
      var payload = { starred_ids: state.starredIds, watch_counts: state.watchCounts, sunday_refresh_tag: state.sundayRefreshTag || '' };
      window.__tdbSupabaseClient.from('profile_kid_loop_progress').upsert({ kid_id: selectedKidId, starred_ids: payload.starred_ids, watch_counts: payload.watch_counts, sunday_refresh_tag: payload.sunday_refresh_tag, updated_at: new Date().toISOString() }, { onConflict: 'kid_id' }).then(function () {}).catch(function () {});
    }
  }

  function showToast(msg) {
    if (!toast) return;
    toast.textContent = String(msg || '');
    toast.classList.remove('is-hidden');
    toast.classList.add('is-visible');
    setTimeout(function () {
      toast.classList.remove('is-visible');
      toast.classList.add('is-hidden');
    }, 3000);
  }

  function getCurrentWeek() {
    var week = Math.floor((Date.now() - START_DATE_MS) / WEEK_MS);
    if (!Number.isFinite(week)) return 0;
    return Math.max(0, Math.min(MAX_WEEK, week));
  }

  function getEffectiveWeek(baseWeek) {
    var bumped = state.starredIds.length >= STAR_GOAL ? 1 : 0;
    return Math.max(0, Math.min(MAX_WEEK, baseWeek + bumped));
  }

  function cardStarred(loopId) {
    return state.starredIds.indexOf(Number(loopId)) !== -1;
  }

  function lazyLoadVideo(videoEl) {
    if (!videoEl || videoEl.getAttribute('data-loaded') === '1') return;
    var source = videoEl.querySelector('source');
    if (!source) return;
    var ds = source.getAttribute('data-src');
    if (!ds) return;
    var ts = typeof trustedScriptURL === 'function' ? trustedScriptURL(ds) : ds;
    if (!ts) return;
    source.src = ts;
    videoEl.setAttribute('data-loaded', '1');
    videoEl.load();
  }

  var lazyObserver = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (!entry.isIntersecting) return;
      lazyLoadVideo(entry.target);
      lazyObserver.unobserve(entry.target);
    });
  }, { rootMargin: '260px 0px' });

  function buildCard(loop, isFirstVisible) {
    var card = document.createElement('article');
    card.className = 'loop-card';
    card.setAttribute('role', 'listitem');
    card.setAttribute('data-loop-id', String(loop.id));

    var mediaWrap = document.createElement('button');
    mediaWrap.type = 'button';
    mediaWrap.className = 'loop-media-wrap';
    mediaWrap.setAttribute('aria-label', 'Play ' + String(loop.title || 'Bible loop'));

    var video = document.createElement('video');
    video.className = 'loop-video';
    video.setAttribute('muted', '');
    video.setAttribute('playsinline', '');
    video.setAttribute('loop', '');
    video.setAttribute('preload', 'none');
    if (!isFirstVisible) video.setAttribute('loading', 'lazy');
    video.setAttribute('data-loop-poster', '/assets/loops/' + String(loop.id) + '.png');
    video.poster = LOOP_THUMB_PLACEHOLDER;
    var source = document.createElement('source');
    source.type = 'video/webm';
    source.setAttribute('data-src', String(loop.file || ''));
    var fallbackImg = document.createElement('img');
    fallbackImg.src = LOOP_THUMB_PLACEHOLDER;
    fallbackImg.alt = String(loop.title || 'Bible story loop') + ' cartoon loop preview' + (cardStarred(loop.id) ? ' — gold star earned' : '');
    if (isFirstVisible) {
      fallbackImg.loading = 'eager';
      try { fallbackImg.fetchPriority = 'high'; } catch (_) {}
    } else {
      fallbackImg.loading = 'lazy';
    }
    video.appendChild(source);
    video.appendChild(fallbackImg);
    video.addEventListener('error', function onLoopCardVideoErr() {
      if (video.getAttribute('data-loop-media-missing') === '1') return;
      video.setAttribute('data-loop-media-missing', '1');
      try { video.pause(); } catch (_) {}
    });
    mediaWrap.appendChild(video);

    var title = document.createElement('h3');
    title.className = 'loop-title';
    title.textContent = String(loop.title || 'Bible Loop');
    var ref = document.createElement('p');
    ref.className = 'loop-verse-ref';
    ref.textContent = String(loop.ref || '');
    var star = document.createElement('p');
    star.className = 'loop-star' + (cardStarred(loop.id) ? ' is-earned' : '');
    star.textContent = cardStarred(loop.id) ? '★ Gold star unlocked' : '☆ Keep watching';

    function playPreview() {
      lazyLoadVideo(video);
      var p = video.play();
      if (p && typeof p.catch === 'function') p.catch(function () {});
    }
    function stopPreview() {
      video.pause();
      if (video.readyState > 0) video.currentTime = 0;
    }

    mediaWrap.addEventListener('mouseenter', playPreview);
    mediaWrap.addEventListener('focus', playPreview);
    mediaWrap.addEventListener('mouseleave', stopPreview);
    mediaWrap.addEventListener('blur', stopPreview);
    mediaWrap.addEventListener('click', function () {
      openModal(loop);
    });

    card.appendChild(mediaWrap);
    card.appendChild(title);
    card.appendChild(ref);
    card.appendChild(star);

    var audioRow = document.createElement('div');
    audioRow.className = 'loop-audio-row';
    var speakerBtn = document.createElement('button');
    speakerBtn.type = 'button';
    var hasAudio = !!String(loop.audio || '').trim();
    speakerBtn.className = 'loop-speaker-btn' + (hasAudio ? '' : ' loop-speaker-btn--disabled');
    speakerBtn.setAttribute('aria-label', hasAudio ? 'Hear the KJV verse for ' + String(loop.title) : 'Audio coming soon for ' + String(loop.title));
    speakerBtn.setAttribute('title', hasAudio ? (loop.kjvText || loop.ref) : 'Coming soon');
    (function wireSpeakerIcon() {
      var spSvg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
      spSvg.setAttribute('aria-hidden', 'true');
      spSvg.setAttribute('focusable', 'false');
      spSvg.setAttribute('viewBox', '0 0 24 24');
      spSvg.setAttribute('width', '18');
      spSvg.setAttribute('height', '18');
      spSvg.setAttribute('fill', 'none');
      spSvg.setAttribute('stroke', 'currentColor');
      spSvg.setAttribute('stroke-width', '2');
      spSvg.setAttribute('stroke-linecap', 'round');
      spSvg.setAttribute('stroke-linejoin', 'round');
      var poly = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
      poly.setAttribute('points', '11 5 6 9 2 9 2 15 6 15 11 19 11 5');
      spSvg.appendChild(poly);
      var pa = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      pa.setAttribute('d', 'M15.54 8.46a5 5 0 0 1 0 7.07');
      spSvg.appendChild(pa);
      var pb = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      pb.setAttribute('d', 'M19.07 4.93a10 10 0 0 1 0 14.14');
      spSvg.appendChild(pb);
      var lbl = document.createElement('span');
      lbl.className = 'loop-speaker-label';
      lbl.textContent = 'Hear verse';
      speakerBtn.appendChild(spSvg);
      speakerBtn.appendChild(lbl);
    })();
    if (!hasAudio) {
      speakerBtn.disabled = true;
    } else {
      var cardAudio = new Audio();
      var audioTrusted = typeof trustedScriptURL === 'function' ? trustedScriptURL(String(loop.audio)) : String(loop.audio);
      if (audioTrusted) cardAudio.src = audioTrusted;
      cardAudio.preload = 'none';
      speakerBtn.addEventListener('click', function (e) {
        e.stopPropagation();
        if (cardAudio.paused) {
          cardAudio.play().catch(function () {});
          speakerBtn.classList.add('loop-speaker-btn--playing');
          speakerBtn.setAttribute('aria-label', 'Pause verse audio for ' + String(loop.title));
        } else {
          cardAudio.pause();
          cardAudio.currentTime = 0;
          speakerBtn.classList.remove('loop-speaker-btn--playing');
          speakerBtn.setAttribute('aria-label', 'Hear the KJV verse for ' + String(loop.title));
        }
      });
      cardAudio.addEventListener('ended', function () {
        speakerBtn.classList.remove('loop-speaker-btn--playing');
        speakerBtn.setAttribute('aria-label', 'Hear the KJV verse for ' + String(loop.title));
      });
      cardAudio.addEventListener('error', function () {
        speakerBtn.classList.remove('loop-speaker-btn--playing');
        speakerBtn.setAttribute('aria-label', 'Hear the KJV verse for ' + String(loop.title));
      });
    }
    audioRow.appendChild(speakerBtn);
    var reportBtn = document.createElement('button');
    reportBtn.type = 'button';
    reportBtn.className = 'loop-report-btn';
    reportBtn.setAttribute('aria-label', 'Report animation mismatch for ' + String(loop.title));
    reportBtn.setAttribute('title', 'Something wrong with this animation? Let us know.');
    var rIcon = document.createElement('span');
    rIcon.setAttribute('aria-hidden', 'true');
    rIcon.textContent = '\u26A0';
    reportBtn.appendChild(rIcon);
    reportBtn.appendChild(document.createTextNode(' Report mismatch'));
    reportBtn.addEventListener('click', function (e) {
      e.stopPropagation();
      var comment = '';
      try { comment = window.prompt('What\'s wrong with this animation? (optional — please do not include private info)', '') || ''; } catch (err) {}
      if (typeof trackEvent === 'function') trackEvent('loop_mismatch_report', { story_id: String(loop.id) });
      var form = LOOP_FEEDBACK_FORM;
      if (form && form.url && form.storyEntry) {
        var m = (loop.file || '').match(/\/([^/]+)\.webm$/);
        var slug = m ? m[1] : String(loop.id);
        var storyVal = encodeURIComponent(String(loop.id) + ' - ' + String(loop.title) + ' (' + slug + ')');
        var q = 'usp=pp_url&' + form.storyEntry + '=' + storyVal;
        if (form.commentEntry && comment) q += '&' + form.commentEntry + '=' + encodeURIComponent(comment);
        var sep = form.url.indexOf('?') >= 0 ? '&' : '?';
        window.open(form.url + sep + q, '_blank');
        try { window.alert('Thanks! Form opened—submit when ready.'); } catch (err) {}
      } else {
        var subject = 'Mismatch Report: ' + String(loop.title) + ' (' + String(loop.id) + ')';
        var body = comment ? encodeURIComponent(comment) : '';
        var mailto = 'mailto:support@todaysdailybattle.com?subject=' + encodeURIComponent(subject) + (body ? '&body=' + body : '');
        window.location.href = mailto;
        try { window.alert('Thanks! We\'ll check it out.'); } catch (err) {}
      }
    });
    audioRow.appendChild(reportBtn);
    card.appendChild(audioRow);

    lazyObserver.observe(video);
    return card;
  }

  function renderGrid() {
    while (grid.firstChild) grid.removeChild(grid.firstChild);
    var fragment = document.createDocumentFragment();
    var visibleLoops = getVisibleLoops();
    visibleLoops.forEach(function (loop, idx) {
      fragment.appendChild(buildCard(loop, idx === 0));
    });
    if (!visibleLoops.length) {
      var empty = document.createElement('p');
      empty.className = 'section-note';
      empty.textContent = 'Nothing in this lane yet\. Try another starter, or return to All unlocked when you want the wider shelf.';
      fragment.appendChild(empty);
    }
    grid.appendChild(fragment);
    var staticStarter = document.getElementById('loop-static-starter');
    if (staticStarter && allLoops.length > 0) staticStarter.classList.add('hidden');
    syncLoopFilterUi(visibleLoops.length);
    updateProgress();
    if (unlockStatus) {
      var playableUnlock = allLoops.filter(function (l) { return !!(l && String(l.file || '').trim()); }).length;
      if (playableUnlock === 0) {
        unlockStatus.textContent = 'Roadmap cards are ready to browse. Cartoon clips and gold stars unlock when files land—KJV text stays readable now.';
      } else if (state.starredIds.length >= STAR_GOAL) {
        unlockStatus.textContent = 'You have ' + STAR_GOAL + ' gold stars—next week’s loops are open early. New drops most Sundays.';
      } else if (state.starredIds.length === 1) {
        unlockStatus.textContent = 'You earned your first gold star. Keep going one loop at a time to unlock next week early.';
      } else {
        unlockStatus.textContent = 'Watch a loop to the end to earn a gold star. Collect ' + STAR_GOAL + ' stars to unlock next week early.';
      }
    }
  }

  function updateLoopPdfExportHint() {
    var el = document.getElementById('loop-pdf-export-count-hint');
    if (!el) return;
    var starCount = state.starredIds.length;
    var visibleCount = getVisibleLoops().length;
    var roadmap = allLoops.length || TOTAL_LOOPS;
    var playable = allLoops.filter(function (l) { return !!(l && String(l.file || '').trim()); }).length;
    el.textContent = starCount + ' gold stars · ' + visibleCount + ' showing · ' + playable + ' playable of ' + roadmap + ' on the roadmap';
  }

  function getLoopWatchCount(loopId) {
    var key = String(loopId);
    var wc = state.watchCounts && typeof state.watchCounts === 'object' ? state.watchCounts : {};
    var n = Number(wc[key]);
    return Number.isFinite(n) && n >= 0 ? n : 0;
  }

  function bumpWatchCount(loopId) {
    var id = Number(loopId);
    if (!Number.isFinite(id)) return;
    var key = String(id);
    var wc = state.watchCounts && typeof state.watchCounts === 'object' ? state.watchCounts : {};
    var prev = Number(wc[key]);
    if (!Number.isFinite(prev) || prev < 0) prev = 0;
    wc[key] = prev + 1;
    state.watchCounts = wc;
  }

  function updateProgress() {
    var roadmap = allLoops.length || TOTAL_LOOPS;
    var playable = allLoops.filter(function (l) { return !!(l && String(l.file || '').trim()); }).length;
    var starCount = state.starredIds.length;
    var meterMax = Math.max(1, STAR_GOAL);
    var pct = Math.round((Math.min(meterMax, starCount) / meterMax) * 100);
    var gentleNote = document.getElementById('loop-progress-gentle-note');
    if (progressText) {
      if (playable === 0 && roadmap > 0) {
        progressText.textContent = roadmap + ' roadmap cards · clips arriving · gold stars wait for playable cartoons';
      } else {
        progressText.textContent = starCount + ' gold star' + (starCount === 1 ? '' : 's') + ' · ' + playable + ' playable of ' + roadmap + ' on the roadmap';
      }
    }
    if (progressMeter) {
      if (playable === 0) {
        progressMeter.setAttribute('aria-valuemax', String(Math.max(1, roadmap)));
        progressMeter.setAttribute('aria-valuenow', '0');
        progressMeter.setAttribute('aria-label', 'Roadmap cards — clips not playable yet');
        if (progressFill) progressFill.style.width = '0%';
      } else {
        progressMeter.setAttribute('aria-valuemax', String(meterMax));
        progressMeter.setAttribute('aria-valuenow', String(Math.min(meterMax, starCount)));
        progressMeter.setAttribute('aria-label', 'Gold stars toward next unlock week');
        if (progressFill) progressFill.style.width = pct + '%';
      }
    } else if (progressFill) {
      progressFill.style.width = (playable === 0 ? 0 : pct) + '%';
    }
    if (gentleNote) {
      gentleNote.textContent = playable === 0
        ? (starCount > 0
          ? 'Stars still count when clips land. Cards and KJV refs stay here meanwhile.'
          : 'Stars count finished clips—not empty roadmap slots. Cards and verses stay ready.')
        : (starCount > 0
          ? 'You already have a start. Keep it light and revisit one loop when you need it.'
          : 'First visit? Your first gold star matters. One finished loop is a real start.');
    }
    if (progressMeter && playable > 0) {
      progressMeter.setAttribute('aria-valuetext', starCount + ' gold stars · ' + playable + ' playable of ' + roadmap + ' roadmap cards');
    } else if (progressMeter && playable === 0) {
      progressMeter.setAttribute('aria-valuetext', roadmap + ' roadmap cards · clips arriving');
    }
    updateLoopPdfExportHint();
  }

  var loopPdfExportWired = false;
  function wireLoopPdfExport() {
    if (loopPdfExportWired) return;
    var btn = document.getElementById('loop-pdf-export');
    if (!btn) return;
    loopPdfExportWired = true;
    btn.addEventListener('click', function () {
      var JsPDF = window.jspdf && window.jspdf.jsPDF;
      if (!JsPDF) {
        showToast('PDF helper still loading—wait a beat, then tap again.');
        return;
      }
      try {
        var doc = new JsPDF('p', 'mm', 'a4');
        var pageW = doc.internal.pageSize.getWidth();
        var margin = 14;
        var y = margin;
        var now = new Date();
        var starCount = state.starredIds.length;
        var visibleLoops = getVisibleLoops();
        var unlockedCount = visibleLoops.length;
        doc.setFontSize(15);
        doc.setFont('helvetica', 'bold');
        doc.text('My Bible Loops Progress', pageW / 2, y, { align: 'center' });
        y += 8;
        doc.setFontSize(10);
        doc.setFont('helvetica', 'normal');
        var summary = 'Generated ' + now.toLocaleString() + ' · ' + unlockedCount + ' loops in this view · ' + state.starredIds.length + ' gold stars on this device';
        var sumLines = doc.splitTextToSize(summary, pageW - margin * 2);
        for (var si = 0; si < sumLines.length; si++) {
          doc.text(sumLines[si], pageW / 2, y, { align: 'center' });
          y += 5;
        }
        y += 3;
        var includeCountsEl = document.getElementById('loop-pdf-include-counts');
        var includeCounts = !!(includeCountsEl && includeCountsEl.checked);
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(10);
        doc.text(includeCounts ? 'Loops you can open now (with full plays logged on this device)' : 'Loops you can open now', margin, y);
        y += 6;
        doc.setFont('helvetica', 'normal');
        doc.setFontSize(9);
        visibleLoops.forEach(function (loop) {
          var line;
          if (includeCounts) {
            var wc = getLoopWatchCount(loop.id);
            var plays = wc + ' full play' + (wc === 1 ? '' : 's');
            var statusLine = cardStarred(loop.id)
              ? ('Gold star · ' + plays)
              : ('Still earning star · ' + plays);
            line = String(loop.title) + ' (' + String(loop.ref) + ') — ' + statusLine;
          } else {
            line = String(loop.title) + ' (' + String(loop.ref) + ')';
          }
          var lines = doc.splitTextToSize(line, pageW - margin * 2);
          for (var li = 0; li < lines.length; li++) {
            if (y > 278) {
              doc.addPage();
              y = margin;
            }
            doc.text(lines[li], margin, y);
            y += 4.5;
          }
          y += 1.5;
        });
        doc.save('my-bible-loops-progress.pdf');
        showToast('PDF downloaded!');
        if (typeof trackEvent === 'function') trackEvent('loop_progress_pdf', { stars: starCount, unlocked: unlockedCount, mode: includeCounts ? 'full' : 'summary' });
      } catch (err) {
        showToast('PDF export did not finish. Try again when you are ready.');
        try { console.error('loop PDF', err); } catch (e2) {}
      }
    });
  }

  function openModal(loop) {
    currentLoop = loop || null;
    if (!currentLoop) return;
    refreshGentleLoopBridgeNextKey();
    var gentleReturnHref = getGentleReturnHref();
    modal.classList.remove('is-hidden');
    modal.classList.toggle('gentle-context', !!(gentleLoopBridge.active && gentleReturnHref));
    modal.scrollTop = 0;
    modalInner.scrollTop = 0;
    if (gentleLoopBridge.active && gentleReturnHref) nextBtn.classList.remove('is-hidden');
    else nextBtn.classList.add('is-hidden');
    nextBtn.textContent = gentleLoopBridge.active
      ? (gentleLoopBridge.nextStoryKey ? 'Back to next gentle story' : 'Back to gentle story library')
      : 'Watch next?';
    gentleReturnLink.textContent = gentleLoopBridge.nextStoryKey ? 'Back to next gentle story' : 'Back to this gentle story';
    gentleReturnLink.href = gentleReturnHref || '#';
    modalTitle.textContent = String(currentLoop.title || 'Bible Loop') + ' • ' + String(currentLoop.ref || '');
    var fileUrl = String(currentLoop.file || '').trim();
    var videoTrusted = typeof trustedScriptURL === 'function' ? trustedScriptURL(fileUrl) : fileUrl;
    if (videoTrusted) modalVideo.src = videoTrusted;
    else modalVideo.removeAttribute('src');
    modalVideo.setAttribute('data-loop-poster', '/assets/loops/' + String(currentLoop.id) + '.png');
    modalVideo.poster = LOOP_THUMB_PLACEHOLDER;
    modalVideo.currentTime = 0;
    modalHelper.textContent = fileUrl
      ? (gentleLoopBridge.active
          ? 'Replay this short loop, then step back into the next gentle story when you are ready.'
          : 'Replay anytime, then jump to a random unlocked loop.')
      : 'This loop’s cartoon file is not on the server yet—no network fetch. When clips are uploaded to /assets/loops/, they will play here automatically.';
    if (String(currentLoop.audio || '').trim()) {
      var modalAudioTrusted = typeof trustedScriptURL === 'function' ? trustedScriptURL(String(currentLoop.audio).trim()) : String(currentLoop.audio).trim();
      if (modalAudioTrusted) modalAudioEl.src = modalAudioTrusted;
      else modalAudioEl.removeAttribute('src');
      modalAudioEl.load();
      var verseText = currentLoop.kjvText ? ('"' + String(currentLoop.kjvText) + '" — ' + String(currentLoop.ref)) : String(currentLoop.ref);
      modalAudioLabel.textContent = verseText;
      modalAudioWrap.classList.remove('is-hidden');
    } else {
      modalAudioEl.removeAttribute('src');
      modalAudioEl.load();
      modalAudioWrap.classList.add('is-hidden');
    }
    var p = modalVideo.play();
    if (p && typeof p.catch === 'function') p.catch(function () {});
  }

  function closeModal() {
    modal.classList.add('is-hidden');
    modal.classList.remove('gentle-context');
    modalVideo.pause();
    modalVideo.removeAttribute('src');
    modalVideo.load();
    modalAudioEl.pause();
    modalAudioEl.removeAttribute('src');
    modalAudioEl.load();
    currentLoop = null;
  }

  function markStar(loopId) {
    var id = Number(loopId);
    if (!Number.isFinite(id)) return;
    if (state.starredIds.indexOf(id) !== -1) return;
    state.starredIds.push(id);
    writeState();
    renderGrid();
  }

  function playRandomUnlocked() {
    if (!unlockedLoops.length) return;
    var pick = unlockedLoops[Math.floor(Math.random() * unlockedLoops.length)];
    if (!pick) return;
    openModal(pick);
  }

  function inSundayRefreshWindow(now) {
    if (!now || typeof now.getDay !== 'function') return false;
    if (now.getDay() !== 0) return false;
    var h = now.getHours();
    var m = now.getMinutes();
    return h === 6 && m >= 0 && m <= 30;
  }

  function todayTag(now) {
    var y = now.getFullYear();
    var mon = String(now.getMonth() + 1).padStart(2, '0');
    var d = String(now.getDate()).padStart(2, '0');
    return y + '-' + mon + '-' + d;
  }

  function recomputeUnlocked() {
    var effectiveWeek = getEffectiveWeek(getCurrentWeek());
    unlockedLoops = allLoops.filter(function (loop) {
      return Number(loop.week) <= effectiveWeek;
    });
    if (weeklyStatus) weeklyStatus.textContent = 'Release week: ' + effectiveWeek + ' of 12.';
    renderGrid();
    maybePrimeGentleLoopBridge();
  }

  function applyLoopsJson(json) {
    if (!Array.isArray(json)) throw new Error('loops.json must be an array.');
    allLoops = json
      .filter(function (item) {
        return item && Number.isFinite(Number(item.id)) && typeof item.title === 'string' && typeof item.file === 'string' && typeof item.ref === 'string' && Number.isFinite(Number(item.week));
      })
      .map(function (item) {
        return {
          id: Number(item.id),
          title: String(item.title),
          file: String(item.file != null ? item.file : '').trim(),
          audio: item.audio ? String(item.audio).trim() : '',
          ref: String(item.ref),
          kjvText: item.kjvText ? String(item.kjvText) : '',
          week: Number(item.week),
          libraryKey: item.libraryKey ? String(item.libraryKey).trim() : ''
        };
      });
    try { localStorage.setItem(LOOPS_CACHE_KEY, JSON.stringify(json)); } catch (e) {}
    TOTAL_LOOPS = Math.max(1, allLoops.length || TOTAL_LOOPS);
    recomputeUnlocked();
  }

  function loadLoops(force) {
    var q = LOOPS_URL.indexOf('?') >= 0 ? '&' : '?';
    var requestUrl = LOOPS_URL + (force ? (q + 'ts=' + Date.now()) : '');
    return fetch(requestUrl, { cache: force ? 'no-store' : 'default' })
      .then(function (resp) {
        if (!resp.ok) throw new Error('Loops did not load.');
        return resp.json();
      })
      .then(function (json) {
        applyLoopsJson(json);
      })
      .catch(function () {
        var usedCache = false;
        try {
          var raw = localStorage.getItem(LOOPS_CACHE_KEY);
          if (raw) {
            var parsed = JSON.parse(raw);
            if (Array.isArray(parsed)) {
              applyLoopsJson(parsed);
              usedCache = true;
            }
          }
        } catch (e) {}
        if (usedCache && weeklyStatus) {
          var ew = getEffectiveWeek(getCurrentWeek());
          weeklyStatus.textContent = 'Offline—still got you. Showing saved loops — release week ' + ew + ' of 12.';
        } else if (weeklyStatus) {
          weeklyStatus.textContent = 'Loops did not load—that happens. That is all right. Check your connection and refresh when you can.';
        }
      });
  }

  modalClose.addEventListener('click', closeModal);
  modal.addEventListener('click', function (event) {
    if (event.target === modal) closeModal();
  });
  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape' && !modal.classList.contains('is-hidden')) closeModal();
  });

  replayBtn.addEventListener('click', function () {
    modalVideo.currentTime = 0;
    if (!(gentleLoopBridge.active && getGentleReturnHref())) nextBtn.classList.add('is-hidden');
    var p = modalVideo.play();
    if (p && typeof p.catch === 'function') p.catch(function () {});
  });

  nextBtn.addEventListener('click', handleLoopNextAction);
  gentleReturnLink.addEventListener('click', function (event) {
    event.preventDefault();
    handleLoopNextAction();
  });

  modalVideo.addEventListener('ended', function () {
    if (currentLoop && currentLoop.id != null) {
      bumpWatchCount(currentLoop.id);
      markStar(currentLoop.id);
      /* markStar skips writeState when star already earned — still persist watchCounts */
      writeState();
    }
    nextBtn.classList.remove('is-hidden');
  });

  function loadStateForSelection(kidId) {
    selectedKidId = kidId || null;
    if (!kidId) {
      state.starredIds = readState().starredIds;
      state.watchCounts = readState().watchCounts;
      state.sundayRefreshTag = readState().sundayRefreshTag;
    } else if (window.__tdbSupabaseClient) {
      window.__tdbSupabaseClient.from('profile_kid_loop_progress').select('starred_ids, watch_counts, sunday_refresh_tag').eq('kid_id', kidId).maybeSingle().then(function (r) {
        var row = r && r.data;
        if (row) {
          state.starredIds = Array.isArray(row.starred_ids) ? row.starred_ids.map(Number) : [];
          state.watchCounts = row.watch_counts && typeof row.watch_counts === 'object' ? row.watch_counts : {};
          state.sundayRefreshTag = typeof row.sunday_refresh_tag === 'string' ? row.sunday_refresh_tag : '';
        } else {
          state.starredIds = [];
          state.watchCounts = {};
          state.sundayRefreshTag = '';
        }
        recomputeUnlocked();
      }).catch(function () { recomputeUnlocked(); });
      return;
    }
    recomputeUnlocked();
  }

  function initLoopKidSelector() {
    var wrap = document.getElementById('loop-kid-selector-wrap');
    var sel = document.getElementById('loop-kid-select');
    if (!wrap || !sel) return;
    var client = window.__tdbSupabaseClient;
    if (!client || !client.auth) return;
    client.auth.getSession().then(function (sess) {
      var session = sess && sess.data ? sess.data.session : null;
      if (!session || !session.user) return;
      client.from('profile_kids').select('id, name').eq('parent_id', session.user.id).order('created_at', { ascending: true }).then(function (r) {
        var kids = (r && r.data) || [];
        if (!kids.length) return;
        wrap.classList.remove('hidden');
        while (sel.firstChild) sel.removeChild(sel.firstChild);
        var opt0 = document.createElement('option');
        opt0.value = '';
        opt0.textContent = 'This device';
        sel.appendChild(opt0);
        kids.forEach(function (k) {
          var opt = document.createElement('option');
          opt.value = k.id;
          opt.textContent = k.name || 'Child';
          sel.appendChild(opt);
        });
        sel.addEventListener('change', function () {
          loadStateForSelection(sel.value || null);
        });
      }).catch(function () {});
    }).catch(function () {});
  }

  document.addEventListener('tdb:loop-kid-changed', function (e) {
    loadStateForSelection(e.detail && e.detail.kidId ? e.detail.kidId : null);
  });

  wireLoopFilters();

  loadLoops(false).then(function () {
    var now = new Date();
    if (inSundayRefreshWindow(now)) {
      var tag = todayTag(now);
      if (state.sundayRefreshTag !== tag) {
        state.sundayRefreshTag = tag;
        writeState();
        loadLoops(true).then(function () { showToast('New stories added.'); });
      }
    }
    initLoopKidSelector();
    wireLoopPdfExport();
    updateLoopPdfExportHint();
  });

  if (!tdbIsPerfMode()) {
    setInterval(function () {
      var now = new Date();
      if (!inSundayRefreshWindow(now)) return;
      var tag = todayTag(now);
      if (state.sundayRefreshTag === tag) return;
      state.sundayRefreshTag = tag;
      writeState();
      loadLoops(true).then(function () { showToast('New stories added.'); });
    }, 60000);
  }
})();

