    safeSessionSet(TDB_COOKIE_CONSENT_KEY, fallbackPayload);
    safeWriteCookie(TDB_COOKIE_CONSENT_KEY, fallbackPayload, TDB_COOKIE_CONSENT_MAX_AGE_SECONDS, { siteWideDomain: true });
