function getDefaultFallbackMessage() {
  var lang = (typeof navigator !== 'undefined' && navigator.language) ? String(navigator.language).toLowerCase().slice(0, 2) : 'en';
  return DEFAULT_FALLBACK_MESSAGES[lang] || DEFAULT_FALLBACK_MESSAGES.en;
}

function getHeartfeltMessageForQuery(normalizedQuery, results) {
  if (!results || results.intent === 'empty') return '';
  var q = String(normalizedQuery || '');
  var tierKey = String((results && results.tier) || 'adult');
  if (results.intent === 'topic' && results.topic && topics[results.topic] && topics[results.topic].explain) {
    var explain = topics[results.topic].explain;
    return String(explain[tierKey] || explain.adult || '').trim();
  }
  if (results.semanticBlendedTopics && results.semanticBlendedTopics.length >= 2) {
    var pairKey = results.semanticBlendedTopics.slice(0, 2).sort().join(',');
    return BLENDED_HEARTFELT_TEMPLATES[pairKey] || BLENDED_HEARTFELT_TEMPLATES.default;
  }
  if (results.semanticTopic && topics[results.semanticTopic] && topics[results.semanticTopic].explain) {
    var semExplain = topics[results.semanticTopic].explain;
    return String(semExplain[tierKey] || semExplain.adult || '').trim();
  }
  if (results.intent === 'reference') {
    var ref = results.verses && results.verses[0] ? results.verses[0].ref : '';
    var ctx = ref && typeof getVerseContext === 'function' ? getVerseContext(ref) : null;
    var app = ctx && ctx.application ? String(ctx.application).trim() : '';
    return app ? ('Take this with you today: ' + app) : 'God sees you and meets you in His Word right where you are today.';
  }
  if (results.intent === 'jesus_said') return 'These are the words of Jesus. Let them steady your heart and guide your next step.';
  for (var i = 0; i < HEARTFELT_INQUIRY_MESSAGES.length; i++) {
    var entry = HEARTFELT_INQUIRY_MESSAGES[i];
    for (var j = 0; j < entry.patterns.length; j++) {
      if (q.indexOf(entry.patterns[j]) !== -1) return entry.message;
    }
  }
  if (typeof resolveSemanticWithScore === 'function' && q.length >= 3) {
    var sem = resolveSemanticWithScore(q);
    if (sem && sem.topic && sem.score >= 0.6 && topics[sem.topic] && topics[sem.topic].explain) {
      var fallbackExplain = topics[sem.topic].explain;
      return String(fallbackExplain[tierKey] || fallbackExplain.adult || '').trim();
    }
  }
  return getDefaultFallbackMessage();
}

// Declared here (before mountRotatingHeroVerse fires) so normalizeEmotionSignal
// can reference EMOTION_ALIAS without hitting a TDZ/undefined error.
var EMOTION_SIGNAL_KEY = 'tdb_emotion_signal_v1';
var EMOTION_ALIAS = {
  fear: 'fear', anxiety: 'fear', anxious: 'fear', worry: 'fear', worried: 'fear', stress: 'fear',
  hope: 'hope', hopeless: 'hope', grief: 'grief', sadness: 'grief', heartache: 'grief',
  courage: 'courage', strength: 'strength', peace: 'peace', family: 'family'
};

function renderSmartResult(query) {
  var key = String(query || '').toLowerCase().trim();
  if (!key) return;
  var container = document.getElementById('feel-results');
  if (!container) return;
  var info = SMART_DICTIONARY[key];
  if (!info && typeof FEEL_TO_SMART !== 'undefined' && FEEL_TO_SMART[key]) {
    info = SMART_DICTIONARY[FEEL_TO_SMART[key]];
  }
  if (!info && typeof resolveSemanticWithScore === 'function' && key.length >= 3) {
    var sem = resolveSemanticWithScore(key);
    if (sem && sem.topic && sem.score >= 0.6 && SMART_DICTIONARY[sem.topic]) {
      info = SMART_DICTIONARY[sem.topic];
    }
  }
  if (!info && typeof resolveTopicFromToken === 'function') {
    var topic = resolveTopicFromToken(key);
    if (!topic && typeof QUERY_TO_TOPIC !== 'undefined') {
      var mapped = QUERY_TO_TOPIC[normalizeInput(key)];
      if (Array.isArray(mapped)) {
        for (var ti = 0; ti < mapped.length; ti++) {
          if (SMART_DICTIONARY[mapped[ti]]) { topic = mapped[ti]; break; }
        }
      } else if (mapped && SMART_DICTIONARY[mapped]) topic = mapped;
    }
    if (topic && SMART_DICTIONARY[topic]) info = SMART_DICTIONARY[topic];
  }
  if (!info && typeof PHRASE_TO_TOKENS !== 'undefined') {
    var norm = (key || '').replace(/[^\w\s]/g, '').replace(/\s+/g, ' ');
    var phraseKeys = Object.keys(PHRASE_TO_TOKENS).sort(function (a, b) { return b.length - a.length; });
    for (var pi = 0; pi < phraseKeys.length; pi++) {
      var pnorm = phraseKeys[pi].replace(/[^\w\s]/g, '').replace(/\s+/g, ' ').toLowerCase();
      if (pnorm.length >= 4 && norm.indexOf(pnorm) !== -1) {
        if (typeof window.runSearchWithInput === 'function') window.runSearchWithInput(query);
        return;
      }
    }
  }
  var wordCount = (key || '').split(/\s+/).filter(function (w) { return w.length >= 2; }).length;
  if (!info) {
    if (key.length < 3) return;
    if (typeof window.runSearchWithInput === 'function') window.runSearchWithInput(query);
    return;
  }
  var verse = null;
  for (var i = 0; i < ROTATING_HERO_VERSES.length; i++) {
    if (ROTATING_HERO_VERSES[i].ref.indexOf(info.verseRef) !== -1) { verse = ROTATING_HERO_VERSES[i]; break; }
  }
  if (!verse) verse = ROTATING_HERO_VERSES[0];

  container.classList.add('tdb-loading');
  try {
  container.innerHTML = '';

  var card = document.createElement('div');
  card.className = 'smart-card';
  card.setAttribute('data-smart-topic', key);

  var heartfelt = document.createElement('p');
  heartfelt.className = 'smart-heartfelt';
  heartfelt.textContent = info.def;

  /* KISS verse stack: KJV → BBE → context */
  var kissVerse = null;
  try {
    var kissBuild =
      (window.TDBBbeSimple && typeof window.TDBBbeSimple.buildKissVerseCard === 'function'
        ? window.TDBBbeSimple.buildKissVerseCard
        : null) ||
      (typeof window.TDB_buildKissVerseCard === 'function' ? window.TDB_buildKissVerseCard : null);
    if (kissBuild) {
      kissVerse = kissBuild({
        ref: verse.ref,
        text: verse.text,
        plain: (verse.breakdown && verse.breakdown[0]) || info.def || '',
        className: 'smart-kiss-verse'
      });
    }
  } catch (eKissSmart) {
    kissVerse = null;
  }
  var verseEl = document.createElement('p');
  verseEl.className = 'smart-verse';
  verseEl.textContent = verse.text;
  var refEl = document.createElement('p');
  refEl.className = 'smart-ref';
  refEl.textContent = verse.ref + ' (KJV)';
  var situationWrap = null;

  var ul = document.createElement('ul');
  ul.className = 'smart-breakdown';
  (verse.breakdown || []).forEach(function(line) {
    var li = document.createElement('li');
    li.textContent = line;
    ul.appendChild(li);
  });

  var actionEl = document.createElement('p');
  actionEl.className = 'smart-action';
  actionEl.textContent = 'Do this: ' + info.action;

  var outcomeEl = document.createElement('p');
  outcomeEl.className = 'smart-outcome';
  outcomeEl.textContent = 'Then: ' + info.outcome;

  card.appendChild(heartfelt);
  if (kissVerse) {
    card.appendChild(kissVerse);
  } else {
    card.appendChild(refEl);
    card.appendChild(verseEl);
    if (situationWrap) card.appendChild(situationWrap);
  }
  card.appendChild(ul);
  card.appendChild(actionEl);
  card.appendChild(outcomeEl);

  // ── Save + Share actions ──
  var actions = document.createElement('div');
  actions.className = 'smart-actions';

  var saveBtn = document.createElement('button');
  saveBtn.type = 'button';
  saveBtn.className = 'smart-action-btn';
  saveBtn.textContent = 'Save to My Study';
  saveBtn.addEventListener('click', function() {
    saveBtn.disabled = true;
    saveDailyVerseToMyVerses(verse.ref, verse.text).then(function (res) {
      saveBtn.textContent = res && res.ok ? (res.already ? 'Already saved \u2713' : 'Saved \u2713') : 'Save failed';
      saveBtn.classList.add('confirmed');
      setTimeout(function () {
        saveBtn.textContent = 'Save to My Study';
        saveBtn.classList.remove('confirmed');
        saveBtn.disabled = false;
      }, 1600);
    }).catch(function () {
      saveBtn.textContent = 'Save failed';
      setTimeout(function () { saveBtn.textContent = 'Save to My Study'; saveBtn.disabled = false; }, 1600);
    });
  });

  var shareBtn = document.createElement('button');
  shareBtn.type = 'button';
  shareBtn.className = 'smart-action-btn';
  shareBtn.textContent = 'Share';
  shareBtn.addEventListener('click', function() {
    var shareText = verse.ref + ': \u201c' + verse.text + '\u201d\n\u2014 todaysdailybattle.com';
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(shareText).then(function() {
        shareBtn.textContent = 'Copied \u2713';
        shareBtn.classList.add('confirmed');
        setTimeout(function() { shareBtn.textContent = 'Share'; shareBtn.classList.remove('confirmed'); }, 1500);
      }).catch(function() {});
    }
  });

  actions.appendChild(saveBtn);
  actions.appendChild(shareBtn);

  // ── Listen button (TTS full card) ──
  var listenBtn = document.createElement('button');
  listenBtn.type = 'button';
  listenBtn.className = 'smart-action-btn smart-listen-btn';
  listenBtn.setAttribute('aria-label', 'Listen slow to this verse and guidance read aloud');
  listenBtn.setAttribute('aria-pressed', 'false');
  listenBtn.textContent = '\uD83D\uDD0A Listen slow';
  var _ttsActive = false;
  listenBtn.addEventListener('click', function() {
    if (_ttsActive && window.speechSynthesis) {
      window.speechSynthesis.cancel();
      _ttsActive = false;
      listenBtn.textContent = '\uD83D\uDD0A Listen slow';
      listenBtn.setAttribute('aria-pressed', 'false');
      return;
    }
    // Try MP3 first
    var audioSrc = '/audio/' + (verse.ref || '').replace(/[\s:]/g, '-').toLowerCase() + '.mp3';
    var audioEl = document.getElementById('smartCardAudio');
    if (!audioEl) {
      audioEl = document.createElement('audio');
      audioEl.id = 'smartCardAudio';
      audioEl.preload = 'none';
      audioEl.setAttribute('aria-hidden', 'true');
      document.body.appendChild(audioEl);
    }
    var smartAudioTrusted = typeof trustedScriptURL === 'function' ? trustedScriptURL(audioSrc) : audioSrc;
    if (smartAudioTrusted) audioEl.src = smartAudioTrusted;
    audioEl.volume = window._tdbAudioVolume !== undefined ? window._tdbAudioVolume : 1;
    var played = false;
    audioEl.oncanplay = function() {
      if (!played) { played = true; audioEl.play().catch(function() { fallbackTTS(); }); }
    };
    audioEl.onerror = function() { fallbackTTS(); };
    listenBtn.textContent = '\u23F8 Stop';
    listenBtn.setAttribute('aria-pressed', 'true');
    audioEl.onended = function() { listenBtn.textContent = '\uD83D\uDD0A Listen slow'; listenBtn.setAttribute('aria-pressed','false'); _ttsActive = false; };
    function fallbackTTS() {
      if (!window.speechSynthesis) { listenBtn.textContent = '\uD83D\uDD0A Listen slow'; return; }
      _ttsActive = true;
      var fullText = info.def + ' \u2026 ' + verse.text + ' \u2014 ' + verse.ref + '. Do this: ' + info.action + '. Then: ' + info.outcome;
      var utt = new SpeechSynthesisUtterance(fullText);
      utt.rate = 0.88; utt.pitch = 1;
      var voices = window.speechSynthesis.getVoices() || [];
      var warm = voices.find(function(v) { return /(samantha|karen|daniel|moira)/i.test(v.name); })
                 || voices.find(function(v) { return v.lang && v.lang.startsWith('en') && v.localService; })
                 || null;
      if (warm) utt.voice = warm;
      utt.onend = function() { listenBtn.textContent = '\uD83D\uDD0A Listen slow'; listenBtn.setAttribute('aria-pressed','false'); _ttsActive = false; };
      utt.onerror = function() { listenBtn.textContent = '\uD83D\uDD0A Listen slow'; listenBtn.setAttribute('aria-pressed','false'); _ttsActive = false; };
      window.speechSynthesis.speak(utt);
    }
    // Small probe — if audio fails to load in 1.2s, go TTS
    setTimeout(function() { if (!played) fallbackTTS(); }, 1200);
  });
  actions.appendChild(listenBtn);
  card.appendChild(actions);

  container.appendChild(card);
  var crisisPattern = /\b(kms|suicidal|suicide|kill\s*myself|end\s*my\s*life|want\s*to\s*die|hurt\s*myself|self\s*harm|end\s*it\s*all|take\s*my\s*life|harm\s*myself|kill\s*someone|hurt\s*someone|harm\s*someone|hurt\s*them|kill\s*them|gonna\s*kill|going\s*to\s*kill|better\s*off\s*dead|cant\s*live\s*like\s*this|end\s*my\s*pain|no\s*point\s*(in\s*)?living|wish\s*(i|im)\s*(was|were)\s*gone|cant\s*go\s*on|im\s*a\s*burden|no\s*reason\s*to\s*live|why\s*bother\s*living|better\s*if\s*(i|im)\s*(wasnt|werent)\s*here|cant\s*keep\s*going|dont\s*want\s*to\s*be\s*here|better\s*off\s*without\s*me|pain\s*to\s*stop\s*forever|wish\s*(i|im)\s*could\s*disappear|hate\s*myself|better\s*off\s*gone|no\s*will\s*to\s*live|feeling\s*trapped|feel\s*trapped|unbearable\s*pain|no\s*way\s*out|stuck\s*in\s*hell|giving\s*away\s*my\s*stuff|making\s*a\s*plan\s*to\s*die|plan\s*to\s*die|researching\s*ways\s*to\s*die|sleep\s*forever|fade\s*away|join\s*loved\s*ones|quiero\s*morir|me\s*quiero\s*matar|no\s*quiero\s*vivir)\b/i;
  var normKey = (key || '').toLowerCase().replace(/[^\w\s]/g, '').replace(/\s+/g, ' ');
  if (crisisPattern.test(applyTypoCorrection(normKey))) {
    var crisisNote = document.createElement('div');
    crisisNote.className = 'crisis-resources-note';
    crisisNote.setAttribute('role', 'complementary');
    crisisNote.setAttribute('aria-label', 'Crisis support resources');
    crisisNote.innerHTML = 'If you\'re in immediate danger or thinking of harming yourself, please reach out right now: <a href="tel:988">Call or text 988</a> (US, 24/7). Text HOME to 741741 for Crisis Text Line. Worldwide: <a href="https://www.befrienders.org/" target="_blank" rel="noopener noreferrer">befrienders.org</a>. <a href="https://findahelpline.com/" target="_blank" rel="noopener noreferrer">findahelpline.com</a> (local options). You\'re not alone.';
    container.appendChild(crisisNote);
  }
  container.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  } finally {
    container.classList.remove('tdb-loading');
  }
}

function mountRotatingHeroVerse() {
  var verses = ROTATING_HERO_VERSES;
  if (!Array.isArray(verses) || verses.length === 0) return;
  // Homepage: loadTodaysVerse() owns hero + #readChapterLink. Never overwrite (would desync ref vs reader URL).
  if (document.querySelector('[data-daily-verse="true"]') || document.getElementById('readChapterLink')) return;
  var order, idx;
  try {
    var rawOrder = localStorage.getItem(HERO_ORDER_KEY);
    order = rawOrder ? JSON.parse(rawOrder) : null;
    idx = parseInt(localStorage.getItem(HERO_IDX_KEY) || '0', 10) || 0;
  } catch (_) { order = null; idx = 0; }
  if (!Array.isArray(order) || order.length !== verses.length) {
    order = verses.map(function (_, i) { return i; });
  }
  if (idx >= verses.length) { idx = 0; }
  var verse = verses[order[idx]];
  var verseEl = document.getElementById('heroVerse');
  var refEl = document.getElementById('heroRef');
  var breakdownEl = document.getElementById('heroBreakdown');
  var appEl = document.getElementById('heroApplication');
  var card = document.getElementById('verseCard');
  var readBtn = document.getElementById('readAloudBtn');
  if (verseEl) verseEl.textContent = verse.text;
  if (refEl) refEl.textContent = verse.ref + ' (KJV)';
  if (breakdownEl) {
    breakdownEl.innerHTML = '';
    var lines = verse.breakdown || [];
    for (var b = 0; b < lines.length; b++) {
      var li = document.createElement('li');
      li.textContent = lines[b];
      breakdownEl.appendChild(li);
    }
  }
  if (appEl) appEl.textContent = verse.app || '';
  if (card) { card.classList.remove('is-loading'); card.classList.add('verse-card-loaded'); }
  if (readBtn) { readBtn.removeAttribute('hidden'); }
  idx++;
  if (idx >= verses.length) {
    idx = 0;
    for (var i = verses.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var tmp = order[i]; order[i] = order[j]; order[j] = tmp;
    }
  }
  try {
    localStorage.setItem(HERO_IDX_KEY, String(idx));
    localStorage.setItem(HERO_ORDER_KEY, JSON.stringify(order));
  } catch (_) {}
  if (typeof updateDailyVerseWhispers === 'function') {
    updateDailyVerseWhispers(verse.ref, verse.text);
  }
}

