function wireNightDawnOverlays() {
  var hour = new Date().getHours();
  var dateKey = getDailyKey();
  var nightEl = document.getElementById('night-falls-overlay');
  var dawnEl = document.getElementById('dawn-overlay');
  if (hour >= 22 && nightEl) {
    try {
      if (sessionStorage.getItem(NIGHT_CLOSE_SHOWN_KEY + dateKey)) return;
      sessionStorage.setItem(NIGHT_CLOSE_SHOWN_KEY + dateKey, '1');
    } catch (e) {}
    nightEl.classList.remove('hidden');
    nightEl.style.display = 'flex';
    nightEl.classList.add('whisper-visible');
    setTimeout(function () {
      nightEl.classList.add('whisper-out');
    }, 9000);
    setTimeout(function () {
      nightEl.style.display = 'none';
      nightEl.classList.remove('whisper-visible', 'whisper-out');
      nightEl.classList.add('hidden');
    }, 10000);
    return;
  }
  if (hour >= 0 && hour < 6 && dawnEl) {
    try {
      if (sessionStorage.getItem(DAWN_SHOWN_KEY + dateKey)) return;
      sessionStorage.setItem(DAWN_SHOWN_KEY + dateKey, '1');
    } catch (e) {}
    dawnEl.classList.remove('hidden');
    dawnEl.style.display = 'flex';
    dawnEl.classList.add('whisper-visible');
    setTimeout(function () {
      dawnEl.classList.add('whisper-out');
    }, 5000);
    setTimeout(function () {
      dawnEl.style.display = 'none';
      dawnEl.classList.remove('whisper-visible', 'whisper-out');
      dawnEl.classList.add('hidden');
    }, 6000);
  }
}

function wireBreatheWithHim() {
  var btn = document.getElementById('breathe-with-him-btn');
  var countEl = document.getElementById('breathe-count-today');
  var card = document.getElementById('daily-battle-card');
  if (!btn || !card) return;
  if (card.classList.contains('verse-card-loaded') || card.querySelector('strong')) btn.style.display = 'inline-block';
  var observer = card && typeof MutationObserver !== 'undefined' ? new MutationObserver(function () {
    if (card.querySelector('strong')) btn.style.display = 'inline-block';
  }) : null;
  if (observer && card) observer.observe(card, { childList: true, subtree: true });
  function getBreatheCount() {
    try { return parseInt(localStorage.getItem(BREATH_COUNT_KEY + getDailyKey()) || '0', 10); } catch (e) { return 0; }
  }
  function setBreatheCount(n) {
    try { localStorage.setItem(BREATH_COUNT_KEY + getDailyKey(), String(n)); } catch (e) {}
  }
  function updateCountDisplay() {
    var n = getBreatheCount();
    if (countEl) {
      countEl.textContent = n > 0 ? 'You breathed ' + n + ' time' + (n === 1 ? '' : 's') + ' today.' : '';
      countEl.style.display = n > 0 ? 'block' : 'none';
    }
  }
  updateCountDisplay();
  btn.addEventListener('click', function () {
    btn.disabled = true;
    btn.textContent = 'In... out... pray.';
    document.body.classList.add('breathe-with-him-active');
    setTimeout(function () {
      document.body.classList.remove('breathe-with-him-active');
      btn.disabled = false;
      btn.textContent = 'Breathe with Him';
      setBreatheCount(getBreatheCount() + 1);
      updateCountDisplay();
    }, 5000);
  });
}

function wireQuickPrayAutocomplete() {
  var input = document.getElementById('quick-pray');
  var list = document.getElementById('quick-pray-suggestions');
  if (!input || !list) return;
  async function fill() {
    if (!supabaseClient) return;
    try {
      var res = await supabaseClient.rpc('get_prayer_intent_suggestions', { p_limit: 10 });
      var intents = (res && res.data) ? res.data : [];
      var seen = {};
      var words = [];
      intents.forEach(function (r) {
        var t = (r.intent && String(r.intent).trim());
        if (t && !seen[t]) { seen[t] = true; words.push(t); }
      });
      words = words.slice(0, 10);
      list.innerHTML = '';
      words.forEach(function (w) {
        var o = document.createElement('option');
        o.value = w;
        list.appendChild(o);
      });
    } catch (e) {}
  }
  fill();
  if (!tdbIsPerfMode()) setInterval(fill, 60000);
}

/**
 * Minimal KJV print sheet (ref + text) in a new window — no new dependencies.
 * @param {{ ref?: string, text?: string, documentTitle?: string, subtitle?: string, trackContext?: string }} opts
 */
function tdbOpenKjvPrintSheet(opts) {
  opts = opts || {};
  var ref = String(opts.ref || '').replace(/\s+/g, ' ').trim();
  var text = String(opts.text || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!ref && !text) {
    if (typeof showEliteToast === 'function') showEliteToast('Nothing to print yet—try again in a moment.');
    return;
  }
  var docTitle = (opts.documentTitle && String(opts.documentTitle).trim()) || (ref ? 'KJV · ' + ref : "Today's Daily Battle");
  var subtitle = String(opts.subtitle || '').trim();
  var w = window.open('', '_blank', 'noopener,noreferrer');
  if (!w || !w.document) {
    if (typeof showEliteToast === 'function') showEliteToast('Print preview needs a new window. Allow pop-ups for this site, or use Copy instead.');
    return;
  }
  var esc = typeof escapeHtml === 'function' ? escapeHtml : function (s) {
    return String(s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  };
  var html = '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + esc(docTitle) + '</title><style>body{font-family:Georgia,Times,serif;line-height:1.55;color:#111;max-width:36rem;margin:1.4rem auto;padding:0 1.2rem}h1{font-size:0.95rem;font-weight:600;margin:0 0 0.2rem;letter-spacing:0.02em;color:#222}.tdb-p-sub{font-size:0.82rem;color:#444;margin:0 0 1.05rem}.tdb-p-body{font-size:1.1rem;margin:0 0 1.4rem;white-space:pre-wrap}footer{font-size:0.72rem;color:#555;border-top:1px solid #ccc;padding-top:0.55rem;margin-top:1.25rem}@page{margin:0.75in}@media print{body{margin:0}}</style></head><body>' +
    (subtitle ? '<p class="tdb-p-sub">' + esc(subtitle) + '</p>' : '') +
    (ref ? '<h1>' + esc(ref) + '</h1>' : '') +
    (text ? '<p class="tdb-p-body">' + esc(text) + '</p>' : '') +
    '<footer>King James Version &middot; todaysdailybattle.com &mdash; for your table or notebook</footer>' +
    '<script>(function(){function go(){setTimeout(function(){try{window.print();}catch(e){}},100);}if(document.readyState==="complete")go();else window.addEventListener("load",go);window.addEventListener("afterprint",function(){try{window.close();}catch(e2){}});})();<\/script></body></html>';
  try {
    var blob = new Blob([html], { type: 'text/html;charset=utf-8' });
    var blobUrl = URL.createObjectURL(blob);
    w.location.assign(blobUrl);
    w.addEventListener('load', function tdbPrintBlobRevoke() {
      w.removeEventListener('load', tdbPrintBlobRevoke);
      setTimeout(function () {
        try {
          URL.revokeObjectURL(blobUrl);
        } catch (eRev) { /* ignore */ }
      }, 120000);
    });
  } catch (e0) {
    if (typeof showEliteToast === 'function') showEliteToast('Print did not open. Try again or use your browser print.');
    return;
  }
  try {
    if (typeof trackEvent === 'function') trackEvent('tdb_print_kjv_sheet', { ctx: String(opts.trackContext || '') });
  } catch (e1) { /* ignore */ }
}
if (typeof window !== 'undefined') window.tdbOpenKjvPrintSheet = tdbOpenKjvPrintSheet;

