function getDailyKidsPrompt() {
  const key = getDailyKey();
  const stored = localStorage.getItem(DAILY_KIDS_STORAGE_KEY);
  if (stored) {
    try {
      const parsed = JSON.parse(stored);
      if (parsed?.key === key && parsed?.item) return parsed.item;
    } catch {}
  }
  const seed = key.split('').reduce((sum, ch) => sum + ch.charCodeAt(0), 0);
  const item = DAILY_KIDS_PROMPTS[seed % DAILY_KIDS_PROMPTS.length];
  localStorage.setItem(DAILY_KIDS_STORAGE_KEY, JSON.stringify({ key, item }));
  try {
    const history = JSON.parse(localStorage.getItem(DAILY_KIDS_HISTORY_KEY) || '[]');
    const next = history.filter(entry => entry.key !== key);
    next.unshift({ key, item });
    localStorage.setItem(DAILY_KIDS_HISTORY_KEY, JSON.stringify(next.slice(0, 14)));
  } catch {}
  return item;
}

function saveStats(stats) {
  localStorage.setItem(STATS_STORAGE_KEY, JSON.stringify(stats));
}

function bumpStat(key) {
  const stats = loadStats();
  stats[key] = (stats[key] || 0) + 1;
  stats.lastActivity = new Date().toISOString();
  saveStats(stats);
}

/**
 * SEARCH ANALYTICS — USER SAFETY IS THE KEY (DO NOT CHANGE)
 * This is a safe place. We NEVER send who searched (no user ID, email, IP, or any identifier).
 * We NEVER send raw search query text (what the user typed).
 * We ONLY send: topic (known topic key, e.g. "hope", "anxiety"), search_type ("keyword"),
 * map_keys (array of semantic labels), semantic_blended (bool), blended_count (number),
 * blended_topics (comma-separated topic keys, e.g. "loneliness,fear"), default_rate (0/1) — never raw query.
 * This protects users from data breaches. Any change that adds query, user_id, email, or
 * similar to search analytics is forbidden. Use trackSearchAnalytics() for all search-related events.
 * See PRIVACY-ANALYTICS.md.
 */
function trackSearchAnalytics(eventName, params) {
  if (eventName !== 'quick_search' && eventName !== 'search_query') return;
  var safe = {};
  if (params && typeof params === 'object') {
    if (params.topic != null && typeof params.topic === 'string') safe.topic = params.topic;
    if (params.search_type != null && typeof params.search_type === 'string') safe.search_type = params.search_type;
    if (Array.isArray(params.map_keys) && params.map_keys.length > 0) {
      var allowed = ['reaction:', 'feeling:', 'outcome:', 'meaning:', 'action:', 'promise:'];
      safe.map_keys = params.map_keys.filter(function (k) {
        return typeof k === 'string' && allowed.some(function (p) { return k.indexOf(p) === 0; });
      }).slice(0, 10);
    }
    if (params.semantic_blended === true) safe.semantic_blended = true;
    if (typeof params.blended_count === 'number' && params.blended_count >= 2) safe.blended_count = params.blended_count;
    if (params.blended_topics != null && typeof params.blended_topics === 'string') {
      var topics = params.blended_topics.split(',').map(function (t) { return String(t || '').trim().toLowerCase(); }).filter(function (t) { return t.length > 0 && /^[a-z0-9_-]+$/.test(t); });
      if (topics.length >= 2 && topics.length <= 5) safe.blended_topics = topics.join(',');
    }
    if (params.heartfelt_template_used != null && typeof params.heartfelt_template_used === 'string') {
      var tpl = String(params.heartfelt_template_used).trim();
      if (/^(pair:[a-z0-9,_-]+|default)$/.test(tpl)) safe.heartfelt_template_used = tpl;
    }
    if (typeof params.default_rate === 'number' && (params.default_rate === 0 || params.default_rate === 1)) safe.default_rate = params.default_rate;
    if (typeof params.verse_count_returned === 'number' && params.verse_count_returned >= 1 && params.verse_count_returned <= 30) safe.verse_count_returned = params.verse_count_returned;
    if (typeof params.used_default_verses === 'number' && (params.used_default_verses === 0 || params.used_default_verses === 1)) safe.used_default_verses = params.used_default_verses;
  }
  trackEvent(eventName, safe);
}

function sanitizeTrackEventParams(params) {
  if (!params || typeof params !== 'object' || Array.isArray(params)) return {};
  var forbiddenKeys = {
    ref: true,
    verse: true,
    verseRef: true,
    query: true,
    search_term: true,
    journal: true,
    email: true,
    user_id: true,
    prayer: true,
    body: true
  };
  var safe = {};
  Object.keys(params).forEach(function (key) {
    if (forbiddenKeys[key]) return;
    safe[key] = params[key];
  });
  return safe;
}

function trackEvent(eventName, params) {
  bumpStat(eventName);
  if (!navigator.onLine) return;
  if (hasTdbAnalyticsConsent() && typeof window.gtag === 'function' && GA_MEASUREMENT_ID) {
    window.gtag('event', eventName, sanitizeTrackEventParams(params));
  }
}
// For search analytics (quick_search, search_query) use trackSearchAnalytics() only — it enforces the allowlist. See PRIVACY-ANALYTICS.md.

