function isMessageBoardSeedItem(item) {
  if (!item || typeof item !== 'object') return false;
  if (item.tdb_board_seed === true) return true;
  var sid = String(item.id || '');
  return sid.indexOf('tdb-seed-prayer-') === 0;
}

function mergeMessageBoardSeeds(data) {
  var list = Array.isArray(data) ? data.slice() : [];
  var realCount = list.filter(function (m) {
    if (!m || typeof m !== 'object' || m.hidden || isMessageBoardSeedItem(m)) return false;
    var t = m.text ?? m.message ?? m.body;
    return typeof t === 'string' && t.trim().length > 0;
  }).length;
  if (realCount >= MESSAGE_BOARD_SEED_THRESHOLD) return list;
  var seeds = getMessageBoardSeedPrayers();
  var have = {};
  for (var i = 0; i < list.length; i++) {
    var m = list[i];
    if (m && m.id != null) have[String(m.id)] = true;
  }
  for (var j = 0; j < seeds.length; j++) {
    if (!have[seeds[j].id]) list.push(seeds[j]);
  }
  return list;
}

async function loadMessages() {
  let data = [];
  if (isSupabaseConfigured() && currentUserId) {
    const res = await supabaseClient
      .from('messages')
      .select('id, user_id, text, created_at, hidden, display_name')
      .order('created_at', { ascending: false })
      .limit(50);
    if (!res.error && Array.isArray(res.data)) data = res.data;
    else if (res.error) {
      const fallback = await supabaseClient
        .from('messages')
        .select('id, user_id, text, created_at, hidden')
        .order('created_at', { ascending: false })
        .limit(50);
      if (!fallback.error && Array.isArray(fallback.data)) data = fallback.data;
    }
  }
  if (!data.length) data = loadMessagesLocal();
  data = mergeMessageBoardSeeds(data);
  return Array.isArray(data) ? data.map(item => item && typeof item === 'object' ? item : null).filter(Boolean) : [];
}

async function postMessage(text) {
  const displayName = loadMessageDisplayName();
  var safeText = truncateForDb(sanitizeUserInput(text), MAX_MESSAGE_TEXT_LENGTH);
  var safeDisplayName = truncateForDb(sanitizeUserInput(displayName), MAX_DISPLAY_NAME_LENGTH);
  if (isSupabaseConfigured() && currentUserId) {
    var postUrl = (window.TDB_CONFIG && window.TDB_CONFIG.POST_MESSAGE_URL) || '';
    if (postUrl) {
      try {
        var session = (typeof supabaseClient !== 'undefined' && supabaseClient.auth) ? (await supabaseClient.auth.getSession()).data?.session : null;
        if (session && session.access_token) {
          var res = await fetch(postUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + session.access_token },
            body: JSON.stringify({ text: safeText, display_name: safeDisplayName })
          });
          var out = await res.json();
          if (res.ok && out && out.id) return out;
          if (res.status === 429) throw new Error(out.error || 'Too many posts. Wait a minute.');
          if (res.status === 401) throw new Error(out.error || 'Session expired.');
        }
      } catch (e) {
        if (e && e.message && (e.message.indexOf('rate') !== -1 || e.message.indexOf('429') !== -1)) throw e;
      }
    }
    const payload = { user_id: currentUserId, text: safeText };
    if (safeDisplayName) payload.display_name = safeDisplayName;
    let { data, error } = await supabaseClient
      .from('messages')
      .insert(payload)
      .select('id, user_id, text, created_at')
      .single();
    if (error && payload.display_name) {
      const retry = await supabaseClient
        .from('messages')
        .insert({ user_id: currentUserId, text: safeText })
        .select('id, user_id, text, created_at')
        .single();
      data = retry.data;
      error = retry.error;
    }
    if (!error && data) return data;
  }
  const local = loadMessagesLocal();
  const item = {
    id: generateUuid(),
    user_id: currentUserId || 'guest',
    text: safeText,
    display_name: safeDisplayName || '',
    created_at: new Date().toISOString()
  };
  local.unshift(item);
  saveMessagesLocal(local);
  bumpStat('messagePosts');
  return item;
}

async function saveNewsletterSignup(email, prefs, name) {
  var safeEmail = truncateForDb(email, MAX_NEWSLETTER_EMAIL_LENGTH);
  var safeName = truncateForDb(name, MAX_DISPLAY_NAME_LENGTH);
  const entry = {
    id: generateUuid(),
    name: safeName || '',
    email: safeEmail,
    daily_opt_in: Boolean(prefs?.daily),
    weekly_opt_in: Boolean(prefs?.weekly),
    preferred_time: prefs?.preferredTime || '',
    created_at: new Date().toISOString()
  };
  const local = loadNewsletterSignups();
  local.unshift(entry);
  saveNewsletterSignups(local);
  bumpStat('newsletterSignups');
  var cloudOk = false;
  if (isSupabaseConfigured()) {
    try {
      // RLS: anon INSERT only on newsletter_signups; no SELECT (see supabase-newsletter-anon-insert.sql).
      var ins = await supabaseClient.from('newsletter_signups').insert({
        email: safeEmail,
        daily_opt_in: Boolean(prefs?.daily),
        weekly_opt_in: Boolean(prefs?.weekly),
        preferred_time: prefs?.preferredTime || null
      });
      cloudOk = !(ins && ins.error);
    } catch {
      cloudOk = false;
    }
  }
  return Object.assign({}, entry, { cloudOk: cloudOk });
}

function renderMessages(items, previewLimit) {
  const list = document.getElementById('message-list');
  const seeMoreBtn = document.getElementById('message-see-more');
  if (!list) return;
  list.innerHTML = '';
  if (!Array.isArray(items)) items = [];
  lastMessageItems = items;
  function safeStr(v, fallback) {
    if (v == null) return fallback || '';
    if (typeof v === 'string') return v;
    return fallback || '';
  }
  const visible = items.filter(item => {
    if (!item || typeof item !== 'object' || item.hidden) return false;
    const t = item.text ?? item.message ?? item.body;
    if (typeof t !== 'string') return false;
    const trimmed = t.trim();
    if (!trimmed.length) return false;
    if (trimmed === '[object Object]' || /^\[object\s+\w+\]$/.test(trimmed)) return false;
    if (trimmed.indexOf('[object ') !== -1) return false;
    return true;
  });
  if (!visible.length) {
    list.textContent = '';
    const wrapEmpty = document.createElement('div');
    wrapEmpty.className = 'message-list-empty';
    const lead = document.createElement('p');
    lead.className = 'message-list-empty-lead';
    lead.textContent =
      'The wall is quiet right now. That is not emptiness—it often means people are praying without posting. When you are ready, one honest line is enough.';
    const sub = document.createElement('p');
    sub.className = 'section-note';
    sub.textContent =
      'You can still lift others with Amen (on this device), or scroll up and share a short prayer, a praise, or a verse that held you.';
    const jump = document.createElement('a');
    jump.className = 'btn btn-secondary';
    jump.style.marginTop = '0.65rem';
    if (typeof currentUserId !== 'undefined' && currentUserId) {
      jump.href = '#message-text';
      jump.textContent = 'Jump to the writing box';
    } else {
      jump.href = '#auth-section';
      jump.textContent = 'Sign in to post (free)';
    }
    wrapEmpty.appendChild(lead);
    wrapEmpty.appendChild(sub);
    wrapEmpty.appendChild(jump);
    list.appendChild(wrapEmpty);
    if (seeMoreBtn) seeMoreBtn.style.display = 'none';
    return;
  }
  const nameMap = loadMessageNameMap();
  const amenCounts = loadAmenCounts();
  const sortValue = document.getElementById('message-sort')?.value || 'newest';
  const sorted = [...visible].sort((a, b) => {
    if (sortValue === 'popular') {
      return (amenCounts[b?.id] || 0) - (amenCounts[a?.id] || 0);
    }
    const aTime = new Date(a?.created_at || 0).getTime();
    const bTime = new Date(b?.created_at || 0).getTime();
    return sortValue === 'oldest' ? aTime - bTime : bTime - aTime;
  });
  const limit = typeof previewLimit === 'number' && previewLimit > 0 ? previewLimit : sorted.length;
  const toRender = sorted.slice(0, limit);
  (function fillMessageFeaturedStrip() {
    const strip = document.getElementById('message-featured-strip');
    const wrap = document.getElementById('message-featured-wrap');
    if (!strip || !wrap) return;
    strip.replaceChildren();
    const ranked = visible
      .map((item) => ({ item: item, n: item && item.id != null ? (amenCounts[item.id] || 0) : 0 }))
      .filter((o) => o.n > 0)
      .sort((a, b) => b.n - a.n)
      .slice(0, 3);
    if (ranked.length === 0) {
      wrap.hidden = true;
      return;
    }
    wrap.hidden = false;
    ranked.forEach(({ item, n }) => {
      const t = safeStr(item.text ?? item.message ?? item.body, '');
      const card = document.createElement('article');
      card.className = 'message-featured-card';
      card.setAttribute('role', 'listitem');
      const p = document.createElement('p');
      p.className = 'message-featured-text';
      const short = t.length > 200 ? t.slice(0, 197) + '\u2026' : t;
      p.textContent = short;
      const meta = document.createElement('p');
      meta.className = 'message-featured-meta';
      meta.textContent = 'Amen \u00B7 ' + n + ' on this device';
      card.appendChild(p);
      card.appendChild(meta);
      strip.appendChild(card);
    });
  })();
  const pinned = buildPinnedEncouragementItem();
  if (pinned) list.appendChild(pinned);
  toRender.forEach(item => {
    if (!item || typeof item !== 'object') return;
    const text = safeStr(item.text ?? item.message ?? item.body, '');
    const displayName = safeStr(item.display_name ?? item.user?.displayName ?? (item.user_id ? nameMap[item.user_id] : null), 'Member');
    if (text.indexOf('[object ') !== -1 || displayName.indexOf('[object ') !== -1) return;
    const row = document.createElement('div');
    row.className = 'list-item';
    const avatar = document.createElement('div');
    avatar.className = 'message-avatar';
    avatar.setAttribute('aria-hidden', 'true');
    const initial = (displayName.charAt(0) || 'M').toUpperCase();
    avatar.textContent = initial;
    const colorIdx = (displayName.charCodeAt(0) || 77) % 6;
    avatar.classList.add('message-avatar-color-' + colorIdx);
    const div = document.createElement('div');
    const strong = document.createElement('strong');
    strong.textContent = displayName;
    const p = document.createElement('p');
    p.textContent = text;
    div.appendChild(strong);
    div.appendChild(p);
    div.className = 'message-item-content';
    row.appendChild(avatar);
    row.appendChild(div);
    const actions = document.createElement('div');
    actions.className = 'message-actions';
    const amenBtn = document.createElement('button');
    const itemId = item.id;
    const amenCount = itemId != null ? (amenCounts[itemId] || 0) : 0;
    amenBtn.type = 'button';
    amenBtn.className = 'message-amen-btn';
    amenBtn.setAttribute(
      'aria-label',
      amenCount ? 'Amen, ' + amenCount + ' on this device' : 'Amen — counted on this device only'
    );
    amenBtn.replaceChildren();
    if (amenCount) {
      amenBtn.appendChild(document.createTextNode('Amen · ' + amenCount));
      const quiet = document.createElement('span');
      quiet.className = 'amen-count-quiet';
      quiet.textContent = ' on this device';
      amenBtn.appendChild(quiet);
    } else {
      amenBtn.appendChild(document.createTextNode('Amen'));
      const quiet = document.createElement('span');
      quiet.className = 'amen-count-quiet';
      quiet.textContent = ' (on this device)';
      amenBtn.appendChild(quiet);
    }
    amenBtn.onclick = () => {
      if (itemId == null) return;
      try {
        if (typeof trackEvent === 'function') trackEvent('prayer_wall_amen_tap', {});
      } catch (_) {}
      const next = loadAmenCounts();
      next[itemId] = (next[itemId] || 0) + 1;
      saveAmenCounts(next);
      renderMessages(lastMessageItems || []);
    };
    actions.appendChild(amenBtn);
    const shareBtn = document.createElement('button');
    shareBtn.textContent = 'Share';
    shareBtn.setAttribute('aria-label', 'Share this message');
    shareBtn.onclick = () => {
      const shareText = (displayName !== 'Member' ? displayName + ': ' : '') + text + '\n— todaysdailybattle.com';
      if (navigator.share && navigator.canShare && navigator.canShare({ text: shareText })) {
        navigator.share({ text: shareText, url: window.location.href, title: 'Message from Today\'s Daily Battle' }).catch(() => {
          navigator.clipboard.writeText(shareText).then(() => { shareBtn.textContent = 'Copied'; setTimeout(() => { shareBtn.textContent = 'Share'; }, 2000); }).catch(() => {});
        });
      } else {
        navigator.clipboard.writeText(shareText).then(() => { shareBtn.textContent = 'Copied'; setTimeout(() => { shareBtn.textContent = 'Share'; }, 2000); }).catch(() => {});
      }
    };
    actions.appendChild(shareBtn);
    if (!isMessageBoardSeedItem(item)) {
      const reportBtn = document.createElement('button');
      reportBtn.textContent = 'Report';
      reportBtn.onclick = async () => {
        const ok = await reportMessageItem(item);
        if (ok) {
          reportBtn.textContent = 'Reported';
          reportBtn.disabled = true;
        } else {
          alert('Report did not go through. Try again in a moment.');
        }
      };
      actions.appendChild(reportBtn);
    }
    row.appendChild(actions);
    list.appendChild(row);
  });
  if (seeMoreBtn) {
    if (sorted.length > limit) {
      seeMoreBtn.style.display = 'inline-block';
      seeMoreBtn.onclick = function () {
        renderMessages(lastMessageItems || []);
      };
    } else {
      seeMoreBtn.style.display = 'none';
    }
  }
  renderDailyEncouragement();
}

function renderDailyEncouragement() {
  const container = document.getElementById('daily-encouragement');
  if (!container) return;
  const fallback = currentDailyBattle?.ref ? currentDailyBattle : getDailyBattleFallback();
  const ref = fallback?.ref || getDailyVerseRef();
  const verseText = ref && bible[ref] ? bible[ref] : '';
  if (!ref || !verseText) {
    container.innerHTML = '<strong>Daily Encouragement</strong><p>Arming you with God\'s Word…</p>';
    return;
  }
  container.innerHTML = '<strong>Daily Encouragement</strong><p>' + escapeHtml(ref) + ' — ' + escapeHtml(verseText) + '</p>';
}

function buildPinnedEncouragementItem() {
  const fallback = currentDailyBattle?.ref ? currentDailyBattle : getDailyBattleFallback();
  const ref = fallback?.ref || getDailyVerseRef();
  const verseText = ref && bible[ref] ? bible[ref] : '';
  if (!ref || !verseText) return null;
  const row = document.createElement('div');
  row.className = 'list-item pinned-message';
  row.innerHTML = '<div><span class="pin-badge">Pinned</span><strong>Daily Encouragement</strong><p>' + escapeHtml(ref) + ' — ' + escapeHtml(verseText) + '</p></div>';
  return row;
}

function copyDailyEncouragement() {
  const fallback = currentDailyBattle?.ref ? currentDailyBattle : getDailyBattleFallback();
  const ref = fallback?.ref || getDailyVerseRef();
  const verseText = ref && bible[ref] ? bible[ref] : '';
  if (!ref || !verseText) {
    alert('Daily encouragement is not on this page yet. Refresh or try again in a moment.');
    return;
  }
  const text = `Daily Encouragement\n${ref}\n${verseText}`;
  navigator.clipboard.writeText(text);
}

var ttsPlaying = false;
var ttsDisabledNoticeShown = false;

function setTtsPlaying(playing) {
  ttsPlaying = playing;
  document.body.classList.toggle('tts-playing', playing);
  var stopBtn = document.getElementById('tts-stop');
  if (stopBtn) stopBtn.style.display = playing ? 'inline-flex' : 'none';
  var readerListen = document.getElementById('reader-listen');
  if (readerListen && !readerListen.hidden) {
    readerListen.textContent = playing ? 'Stop' : 'Listen';
    readerListen.setAttribute('aria-pressed', playing ? 'true' : 'false');
    readerListen.setAttribute('aria-label', playing ? 'Stop chapter narration' : 'Listen to this chapter on your device');
  }
}

if (typeof window !== 'undefined' && !window.__tdbVerseNarrTtsBridge) {
  window.__tdbVerseNarrTtsBridge = true;
  window.addEventListener('tdb-verse-tts-playing', function (e) {
    var on = !!(e && e.detail && e.detail.playing);
    if (typeof setTtsPlaying === 'function') setTtsPlaying(on);
  });
}

function stopTts() {
  var wasPlaying = ttsPlaying;
  if (window.TDBVerseNarration && typeof window.TDBVerseNarration.stop === 'function') {
    window.TDBVerseNarration.stop();
  }
  if ('speechSynthesis' in window) window.speechSynthesis.cancel();
  setTtsPlaying(false);
  if (wasPlaying) {
    try {
      if (typeof trackEvent === 'function') trackEvent('chapter_reader_listen_stop', {});
    } catch (e) {}
  }
}

function speakVerse(ref, text, ttsOptions) {
  if (!ref || !text) return;
  if (!('speechSynthesis' in window) || typeof SpeechSynthesisUtterance === 'undefined') {
    alert('Listen is not open in this browser. Use KJV Audio instead.');
    return;
  }
  var cleaned = String(text || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  if (!cleaned) return;
  try { window.speechSynthesis.cancel(); } catch (e) {}
  setTtsPlaying(false);
  var utterance = new SpeechSynthesisUtterance(cleaned);
  var selected = null;
  try { selected = typeof getSelectedVoice === 'function' ? getSelectedVoice() : null; } catch (e2) { selected = null; }
  if (selected) utterance.voice = selected;
  var utteranceRate = 1;
  var calmChapter = ttsOptions && ttsOptions.calmChapter;
  try {
    var savedRate = localStorage.getItem(TTS_RATE_KEY);
    utteranceRate = Math.min(1.5, Math.max(0.5, Number(savedRate) || 1));
  } catch (e3) {
    utteranceRate = 1;
  }
  if (calmChapter) {
    utteranceRate = Math.min(utteranceRate, 0.78);
  }
  utterance.rate = utteranceRate;
  utterance.pitch = calmChapter ? 0.97 : 1;
  utterance.onstart = function () { setTtsPlaying(true); };
  utterance.onend = function () { setTtsPlaying(false); };
  utterance.onerror = function () {
    setTtsPlaying(false);
    if (!ttsDisabledNoticeShown) {
      ttsDisabledNoticeShown = true;
      alert('Read-aloud could not start. Try Listen again, or use KJV Audio.');
    }
  };
  try {
    window.speechSynthesis.speak(utterance);
  } catch (speakErr) {
    setTtsPlaying(false);
    if (!ttsDisabledNoticeShown) {
      ttsDisabledNoticeShown = true;
      alert('Read-aloud could not start on this device. Use KJV Audio instead.');
    }
  }
}

/** Verse lines only — strips reference prefix from each line for clearer TTS. */
function getReaderChapterPlainTextFromDom(output) {
  if (!output || !output.querySelectorAll) return '';
  var lines = output.querySelectorAll('.context-line');
  if (!lines.length) return '';
  var parts = [];
  for (var i = 0; i < lines.length; i++) {
    var el = lines[i];
    var stored = '';
    try { stored = String(el.getAttribute && el.getAttribute('data-verse-text') || '').trim(); } catch (eSt) { stored = ''; }
    var t = stored;
    if (!t || /Verse breakdown|Pick your style:/i.test(t)) {
      var clone = el.cloneNode(true);
      var kill = clone.querySelectorAll('.tdb-verse-breakdown-inline, .reader-verse-xref-btn, .reader-verse-wordstudy-btn, .tdb-breakdown-btn');
      for (var ki = 0; ki < kill.length; ki++) {
        if (kill[ki].parentNode) kill[ki].parentNode.removeChild(kill[ki]);
      }
      var strong = clone.querySelector('strong');
      if (strong) strong.remove();
      t = (clone.textContent || '').replace(/\s+/g, ' ').trim();
    }
    if (t && /Verse breakdown|Pick your style:/i.test(t)) t = '';
    if (t) parts.push(t);
  }
  return parts.join(' ');
}

function speakChapter(book, chapter) {
  const key = `${book} ${chapter}`;
  const output = document.getElementById('reader-output');
  const lineEls = output && output.querySelectorAll ? output.querySelectorAll('.context-line') : null;
  if (
    window.TDBVerseNarration &&
    typeof window.TDBVerseNarration.speakReaderLines === 'function' &&
    lineEls &&
    lineEls.length
  ) {
    try {
      trackEvent('chapter_reader_listen', { book: String(book || ''), chapter: String(chapter || '') });
    } catch (e) {}
    window.TDBVerseNarration.speakReaderLines(Array.prototype.slice.call(lineEls), {
      calm: true,
      repeat: window.TDBVerseNarration.getRepeat(),
      phrasePause: window.TDBVerseNarration.getPhrasePause()
    });
    return;
  }
  let verses = chapterIndex[key];
  let text = '';
  if (verses && verses.length) {
    text = verses.map(function (v) { return v.text || ''; }).join(' ').replace(/\s+/g, ' ').trim();
  } else {
    text = output ? getReaderChapterPlainTextFromDom(output) : '';
  }
  if (!text) {
    alert('Listen needs chapter text first. Open a chapter, then tap Listen.');
    return;
  }
  try {
    trackEvent('chapter_reader_listen', { book: String(book || ''), chapter: String(chapter || '') });
  } catch (e) {}
  speakVerse(key, text, { calmChapter: true });
}

function getVersePageUrl(ref) {
  var base = window.location.origin + ((window.location.pathname || '/').replace(/\/[^/]*$/, '') || '/');
  if (!base.endsWith('/')) base += '/';
  return base + (base.endsWith('index.html') ? '' : 'index.html') + '?ref=' + encodeURIComponent(ref);
}

function buildVerseShareText(ref, text) {
  const clean = (text || '').replace(/<[^>]+>/g, '').trim();
  const short = clean.length > 120 ? clean.slice(0, 117) + '\u2026' : clean;
  return 'Found this KJV verse helpful today: ' + short + ' via @todaysdailybattle \u2694\uFE0F';
}

function shareVerse(ref, text) {
  const shareText = buildVerseShareText(ref, text);
  emitEasterEgg('share_cape', { source: 'verse' });
  if (navigator.share) {
    navigator.share({ text: shareText, url: getVersePageUrl(ref) }).catch(() => {});
    return;
  }
  navigator.clipboard.writeText(shareText);
  alert('Share text copied.');
}

function buildTweetShareUrl(ref, text) {
  const clean = text.replace(/<[^>]+>/g, '');
  const msg = `"${clean.substring(0, 200)}${clean.length > 200 ? '…' : ''}" — ${ref}\n\n${window.location.origin}`;
  return `https://twitter.com/intent/tweet?text=${encodeURIComponent(msg)}`;
}

function buildFacebookShareUrl(ref) {
  const base = window.location.origin + (window.location.pathname || '/').replace(/\/[^/]*$/, '') || '';
  const verseUrl = `${base.replace(/\/$/, '')}/?ref=${encodeURIComponent(ref)}`;
  return `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(verseUrl)}`;
}

function buildWhatsAppShareUrl(ref, text) {
  const clean = (text || '').replace(/<[^>]+>/g, '').trim();
  const url = getVersePageUrl(ref);
  const msg = `Battling today? Here's hope from God's Word:\n${ref}\n${clean}\n\n${url}`;
  return 'https://wa.me/?text=' + encodeURIComponent(msg);
}

function buildPrayerFromVerse(ref, text) {
  const clean = (text || '').replace(/<[^>]+>/g, '').trim();
  const short = clean.length > 80 ? clean.substring(0, 77) + '…' : clean;
  return `Lord, thank You for Your Word in ${ref}. Let this truth sink into my heart: "${short}" Help me live by it today. Amen.`;
}

function buildKjvAudioUrl(ref) {
  if (!ref || typeof ref !== 'string') return 'https://www.biblegateway.com/passage/?version=KJV';
  const normalized = ref.trim().replace(/\s+/g, ' ');
  const encoded = encodeURIComponent(normalized).replace(/%20/g, '+');
  return `https://www.biblegateway.com/passage/?search=${encoded}&version=KJV`;
}

