function renderReaderCrossRefsPanel(book, chapter) {
  const panel = document.getElementById('reader-crossrefs-panel');
  if (!panel) return;
  const params = new URLSearchParams(window.location.search || '');
  let fromRaw = params.get('fromRef') || '';
  try {
    if (fromRaw) fromRaw = decodeURIComponent(fromRaw);
  } catch (e0) {
    /* ignore */
  }
  fromRaw = String(fromRaw || '').replace(/\s+/g, ' ').trim();
  const backCanon = fromRaw ? parseReference(fromRaw) || fromRaw : '';
  let refRaw = params.get('ref') || '';
  try {
    if (refRaw) refRaw = decodeURIComponent(refRaw);
  } catch (e1) {
    /* ignore */
  }
  refRaw = String(refRaw || '').replace(/\s+/g, ' ').trim();
  const anchorRef = parseReference(refRaw) || refRaw;
  const ck = anchorRef ? getChapterKey(anchorRef) : null;
  const b = String(book || '').trim();
  const ch = String(chapter || '').trim();
  const anchorOk = ck === `${b} ${ch}` && !!anchorRef;

  panel.textContent = '';
  panel.classList.add('hidden');

  const frag = document.createDocumentFragment();
  if (backCanon) {
    const backKey = getChapterKey(backCanon);
    if (backKey) {
      const backP = document.createElement('p');
      backP.className = 'reader-crossrefs-back';
      const backA = document.createElement('a');
      backA.href = buildReaderUrl(backCanon);
      backA.textContent = `Back to ${backCanon}`;
      backP.appendChild(backA);
      frag.appendChild(backP);
    }
  }

  if (!anchorOk && frag.childNodes.length === 0) return;

  ensureCrossRefsLoaded().then((full) => {
    const map = full && full.refs ? full.refs : {};
    if (anchorOk) {
      const list = map && map[anchorRef];
      if (Array.isArray(list) && list.length) {
        const title = document.createElement('h3');
        title.className = 'reader-crossrefs-title';
        title.textContent = `Related verses for ${anchorRef}`;
        frag.appendChild(title);
        const ul = document.createElement('ul');
        ul.className = 'reader-crossrefs-list';
        list.slice(0, 10).forEach((r) => {
          const refStr = String(r || '').trim();
          if (!refStr) return;
          const li = document.createElement('li');
          const a = document.createElement('a');
          a.href = buildReaderUrl(refStr, anchorRef);
          a.textContent = refStr;
          li.appendChild(a);
          ul.appendChild(li);
        });
        frag.appendChild(ul);
      }
    }
    if (frag.childNodes.length) {
      panel.appendChild(frag);
      panel.classList.remove('hidden');
    }
  });
}

var readerXrefsLastAnchorRef = '';
var readerXrefsLastVerseSnippet = '';
/** @type {Element|null} */
var readerXrefsFocusBeforeOpen = null;

function tdbListDialogFocusables(panel) {
  if (!panel || !panel.querySelectorAll) return [];
  const sel =
    'a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),summary,[tabindex]:not([tabindex="-1"])';
  return Array.prototype.slice.call(panel.querySelectorAll(sel)).filter((el) => {
    if (el.getAttribute && el.getAttribute('tabindex') === '-1') return false;
    if (el.closest && el.closest('[hidden]')) return false;
    const s = getComputedStyle(el);
    if (s.visibility === 'hidden' || s.display === 'none') return false;
    return el.getClientRects && el.getClientRects().length > 0;
  });
}

function tdbTrapDialogTabKeydown(ev, panel) {
  if (ev.key !== 'Tab' || !panel) return;
  const list = tdbListDialogFocusables(panel);
  if (list.length < 2) return;
  const first = list[0];
  const last = list[list.length - 1];
  if (ev.shiftKey) {
    if (document.activeElement === first) {
      last.focus();
      ev.preventDefault();
    }
  } else if (document.activeElement === last) {
    first.focus();
    ev.preventDefault();
  }
}
try {
  if (typeof globalThis !== 'undefined') globalThis.tdbTrapDialogTabKeydown = tdbTrapDialogTabKeydown;
} catch (e) {}

function normXrefRefKey(r) {
  return String(r || '')
    .replace(/\s+/g, ' ')
    .trim();
}

function partitionMoreXrefsByTheme(more, full) {
  const normMore = (more || []).map((r) => normXrefRefKey(r)).filter(Boolean);
  if (!normMore.length) return [];
  const chains = full && full.chains && typeof full.chains === 'object' ? full.chains : {};
  const themeGroups = full && Array.isArray(full.themeGroups) ? full.themeGroups : [];
  if (!themeGroups.length) {
    return [{ chainKey: null, title: 'More related passages', blurb: '', verses: normMore }];
  }
  const assigned = new Set();
  const sections = [];
  themeGroups.forEach((tg) => {
    if (!tg || !tg.title || !Array.isArray(tg.keys)) return;
    const inTheme = new Set();
    tg.keys.forEach((ck) => {
      const ch = chains[ck];
      if (!ch || !Array.isArray(ch.verses)) return;
      ch.verses.forEach((v) => inTheme.add(normXrefRefKey(v)));
    });
    const bucket = [];
    normMore.forEach((nr) => {
      if (assigned.has(nr)) return;
      if (inTheme.has(nr)) bucket.push(nr);
    });
    if (bucket.length) {
      bucket.forEach((nr) => assigned.add(nr));
      sections.push({
        chainKey: null,
        title: `${String(tg.title)} — related passages`,
        blurb: 'From your verse’s list, placed with the theme that shares these curated chains.',
        verses: bucket
      });
    }
  });
  const rest = normMore.filter((nr) => !assigned.has(nr));
  if (rest.length) {
    sections.push({ chainKey: null, title: 'More related passages', blurb: '', verses: rest });
  }
  return sections;
}

function buildCrossRefSheetSections(anchorRef, full) {
  const refsMap = full && full.refs ? full.refs : {};
  const chains = full && full.chains ? full.chains : {};
  const nref = normXrefRefKey(parseReference(anchorRef) || anchorRef);
  const seen = new Set();
  const sections = [];

  Object.keys(chains).forEach((key) => {
    const ch = chains[key];
    if (!ch || !ch.title || !Array.isArray(ch.verses)) return;
    const verses = ch.verses.map(normXrefRefKey);
    const inChain = verses.indexOf(nref) !== -1 || normXrefRefKey(ch.anchor) === nref;
    if (!inChain) return;
    const others = verses.filter((v) => v && v !== nref).slice(0, 12);
    if (!others.length) return;
    sections.push({
      chainKey: key,
      title: String(ch.title),
      blurb: ch.blurb ? String(ch.blurb) : '',
      verses: others
    });
    others.forEach((v) => seen.add(v));
  });

  const flat = Array.isArray(refsMap[nref]) ? refsMap[nref].map(normXrefRefKey).filter(Boolean) : [];
  const more = flat.filter((v) => v && v !== nref && !seen.has(v)).slice(0, 18);
  if (more.length) {
    const parts = partitionMoreXrefsByTheme(more, full);
    parts.forEach((p) => {
      sections.push(p);
      p.verses.forEach((v) => seen.add(v));
    });
  }

  return { sections, flatLen: flat.length };
}

function getVerseSnippetForXrefRef(ref) {
  const r = normXrefRefKey(parseReference(ref) || ref);
  if (!r) return '';
  if (typeof bible !== 'undefined' && bible && bible[r]) {
    return String(bible[r])
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  }
  return '';
}

function getVerseSnippetFromContextLine(line) {
  if (!line) return '';
  const stored = String((line.getAttribute && line.getAttribute('data-verse-text')) || '').trim();
  if (stored && !/Verse breakdown|Pick your style:/i.test(stored)) return stored;
  const clone = line.cloneNode(true);
  clone.querySelectorAll('.tdb-verse-breakdown-inline, .reader-verse-xref-btn, .reader-verse-wordstudy-btn, .tdb-breakdown-btn').forEach((n) => n.remove());
  const strong = clone.querySelector('strong');
  if (strong) strong.remove();
  return String(clone.textContent || '')
    .replace(/\s+/g, ' ')
    .trim();
}

function createReaderXrefSectionEl(sec, nref) {
  const wrap = document.createElement('section');
  wrap.className = 'reader-xrefs-group';
  wrap.dataset.xrefFilterText = `${sec.title} ${sec.verses.join(' ')}`.toLowerCase();
  const ht = document.createElement('h3');
  ht.className = 'reader-xrefs-group-title';
  ht.textContent = sec.title;
  wrap.appendChild(ht);
  if (sec.blurb) {
    const bp = document.createElement('p');
    bp.className = 'reader-xrefs-group-blurb';
    bp.textContent = sec.blurb;
    wrap.appendChild(bp);
  }
  const ul = document.createElement('ul');
  ul.className = 'reader-xrefs-group-list';
  sec.verses.forEach((vr) => {
    const li = document.createElement('li');
    li.dataset.xrefFilterText = vr.toLowerCase();
    const a = document.createElement('a');
    a.href = buildReaderUrl(vr, nref);
    a.className = 'reader-xrefs-open-link';
    a.textContent = vr;
    li.appendChild(a);
    ul.appendChild(li);
  });
  wrap.appendChild(ul);
  return wrap;
}

function populateReaderXrefsSheetBody(anchorRef, verseText, full) {
  const body = document.getElementById('reader-xrefs-sheet-body');
  const emptyEl = document.getElementById('reader-xrefs-sheet-empty');
  if (!body) return;
  body.textContent = '';
  const nref = normXrefRefKey(parseReference(anchorRef) || anchorRef);
  readerXrefsLastVerseSnippet = String(verseText || getVerseSnippetForXrefRef(nref) || '')
    .replace(/\s+/g, ' ')
    .trim();
  const built = buildCrossRefSheetSections(nref, full);

  const anchorBlock = document.createElement('div');
  anchorBlock.className = 'reader-xrefs-anchor-block';
  const ah = document.createElement('p');
  ah.className = 'reader-xrefs-anchor-ref';
  ah.textContent = nref;
  anchorBlock.appendChild(ah);
  const at = document.createElement('p');
  at.className = 'reader-xrefs-anchor-text';
  at.textContent = verseText || getVerseSnippetForXrefRef(nref) || 'KJV text loads with the chapter in this reader.';
  anchorBlock.appendChild(at);
  body.appendChild(anchorBlock);

  const sheetIntro = document.createElement('p');
  sheetIntro.className = 'reader-xrefs-sheet-intro';
  sheetIntro.dataset.xrefFilterText =
    'themes comfort grief peace prayer faith grace christ union identity related passages cross references';
  sheetIntro.textContent =
    'Curated chains appear under each theme when your verse belongs there. When this verse has its own short list, those passages are grouped the same way; use the filter to narrow long lists. Anything still open shows under “More related passages.”';
  body.appendChild(sheetIntro);

  if (!built.sections.length) {
    if (emptyEl) {
      emptyEl.textContent =
        'No curated cross-references for this verse are in the offline list yet\u2014you are still welcome here. Try another line, or open the Bible Tool for lookup. You can still tap Study this verse below for KJV word help on this line.';
      emptyEl.classList.remove('hidden');
    }
    return;
  }
  if (emptyEl) emptyEl.classList.add('hidden');

  const byChain = new Map();
  built.sections.forEach((sec) => {
    if (sec.chainKey) byChain.set(sec.chainKey, sec);
  });
  const usedChains = new Set();
  const themeGroups = full && Array.isArray(full.themeGroups) ? full.themeGroups : [];

  themeGroups.forEach((tg) => {
    if (!tg || !tg.title || !Array.isArray(tg.keys)) return;
    const themeWrap = document.createElement('section');
    themeWrap.className = 'reader-xrefs-theme';
    const h2 = document.createElement('h2');
    h2.className = 'reader-xrefs-theme-title';
    h2.textContent = String(tg.title);
    themeWrap.appendChild(h2);
    if (tg.subtitle) {
      const sub = document.createElement('p');
      sub.className = 'reader-xrefs-theme-sub';
      sub.textContent = String(tg.subtitle);
      sub.dataset.xrefFilterText = String(tg.subtitle).toLowerCase();
      themeWrap.appendChild(sub);
    }
    themeWrap.dataset.xrefFilterText = (String(tg.title) + ' ' + (tg.subtitle ? String(tg.subtitle) : '')).toLowerCase();
    let any = false;
    tg.keys.forEach((ck) => {
      const sec = byChain.get(ck);
      if (!sec) return;
      any = true;
      usedChains.add(ck);
      const inner = createReaderXrefSectionEl(sec, nref);
      inner.dataset.xrefFilterText = `${themeWrap.dataset.xrefFilterText} ${inner.dataset.xrefFilterText || ''}`;
      themeWrap.appendChild(inner);
    });
    if (any) body.appendChild(themeWrap);
  });

  built.sections.forEach((sec) => {
    if (sec.chainKey && usedChains.has(sec.chainKey)) return;
    body.appendChild(createReaderXrefSectionEl(sec, nref));
  });
}

function applyReaderXrefsFilter(query) {
  const q = String(query || '')
    .trim()
    .toLowerCase();
  document.querySelectorAll('#reader-xrefs-sheet-body .reader-xrefs-group').forEach((sec) => {
    const blob = sec.dataset.xrefFilterText || '';
    let anyLi = false;
    sec.querySelectorAll('li[data-xref-filter-text]').forEach((li) => {
      const t = li.dataset.xrefFilterText || '';
      const match = !q || t.indexOf(q) !== -1 || blob.indexOf(q) !== -1;
      li.classList.toggle('hidden', !match);
      if (match) anyLi = true;
    });
    sec.classList.toggle('hidden', !!q && !anyLi && blob.indexOf(q) === -1);
  });
  document.querySelectorAll('#reader-xrefs-sheet-body .reader-xrefs-theme').forEach((tw) => {
    const innerGroups = tw.querySelectorAll(':scope > .reader-xrefs-group');
    let anyVisible = false;
    innerGroups.forEach((g) => {
      if (!g.classList.contains('hidden')) anyVisible = true;
    });
    const blob = (tw.dataset.xrefFilterText || '').toLowerCase();
    tw.querySelectorAll(':scope > .reader-xrefs-theme-sub').forEach((sub) => {
      const sb = (sub.dataset.xrefFilterText || sub.textContent || '').toLowerCase();
      if (q && sb.indexOf(q) !== -1) anyVisible = true;
    });
    tw.classList.toggle('hidden', !!q && !anyVisible && blob.indexOf(q) === -1);
  });
  const intro = document.querySelector('#reader-xrefs-sheet-body .reader-xrefs-sheet-intro');
  if (intro) {
    const ib = (intro.dataset.xrefFilterText || intro.textContent || '').toLowerCase();
    intro.classList.toggle('hidden', !!q && ib.indexOf(q) === -1);
  }
}

function openReaderCrossrefsSheet(anchorRef, verseTextOpt) {
  const layer = document.getElementById('reader-xrefs-layer');
  if (!layer) return;
  readerXrefsFocusBeforeOpen = document.activeElement;
  readerXrefsLastAnchorRef = normXrefRefKey(parseReference(anchorRef) || anchorRef);
  const filterIn = document.getElementById('reader-xrefs-filter');
  if (filterIn) filterIn.value = '';
  ensureCrossRefsLoaded().then((full) => {
    populateReaderXrefsSheetBody(readerXrefsLastAnchorRef, verseTextOpt || '', full);
    layer.classList.remove('hidden');
    layer.setAttribute('aria-hidden', 'false');
    document.body.classList.add('reader-xrefs-open');
    try {
      trackEvent('reader_xrefs_sheet_open', {});
    } catch (e) {
      /* ignore */
    }
    const backBtn = document.getElementById('reader-xrefs-back');
    if (backBtn) backBtn.focus();
    const wsOpenStudy = document.getElementById('reader-xrefs-wordstudy-open');
    if (wsOpenStudy && readerXrefsLastAnchorRef) {
      wsOpenStudy.setAttribute('aria-label', 'Open verse study for ' + readerXrefsLastAnchorRef);
    }
  });
}

function closeReaderCrossrefsSheet(opts) {
  const layer = document.getElementById('reader-xrefs-layer');
  if (!layer) return;
  layer.classList.add('hidden');
  layer.setAttribute('aria-hidden', 'true');
  document.body.classList.remove('reader-xrefs-open');
  const skipRestore = opts && opts.skipFocusRestore;
  const ret = readerXrefsFocusBeforeOpen;
  readerXrefsFocusBeforeOpen = null;
  if (!skipRestore && ret && typeof ret.focus === 'function') {
    try {
      if (ret.isConnected) ret.focus();
    } catch (e) {
      /* ignore */
    }
  }
}

function attachReaderVerseXrefControls() {
  const out = document.getElementById('reader-output');
  if (!out) return;
  out.querySelectorAll('.context-line').forEach((line) => {
    if (line.querySelector('.reader-verse-xref-btn')) return;
    const ref = line.dataset.ref;
    if (!ref) return;
    line.classList.add('reader-verse-line--xref');
    line.classList.add('reader-verse-line--tools');
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'reader-verse-xref-btn';
    btn.setAttribute('aria-label', `Cross references for ${ref}`);
    btn.setAttribute('title', 'Cross references');
    btn.appendChild(document.createTextNode('\u26D3'));
    btn.addEventListener('click', (ev) => {
      ev.preventDefault();
      ev.stopPropagation();
      const txt = getVerseSnippetFromContextLine(line);
      openReaderCrossrefsSheet(ref, txt);
    });
    line.appendChild(btn);
  });
}

function saveBibleToolNoteAppend(ref, noteText) {
  try {
    const notesKey = 'tdb_bible_tool_notes';
    const raw = localStorage.getItem(notesKey);
    let obj = raw ? JSON.parse(raw) : {};
    if (!obj || typeof obj !== 'object') obj = {};
    const r = String(ref || '').replace(/\s+/g, ' ').trim();
    if (!r) return false;
    const add = String(noteText || '').trim();
    if (!add) return false;
    const prev = String(obj[r] || '').trim();
    obj[r] = prev ? `${prev}\n\n${add}` : add;
    localStorage.setItem(notesKey, JSON.stringify(obj));
    return true;
  } catch (e) {
    return false;
  }
}

function saveReaderXrefsToMyStudy() {
  const r = readerXrefsLastAnchorRef;
  if (!r) return;
  ensureCrossRefsLoaded().then((full) => {
    const built = buildCrossRefSheetSections(r, full);
    const lines = ['Cross-references (chapter reader)'];
    built.sections.forEach((s) => {
      lines.push(`— ${s.title}: ${s.verses.join('; ')}`);
    });
    const ok = saveBibleToolNoteAppend(r, lines.join('\n'));
    try {
      trackEvent('reader_xrefs_save_mystudy', { ok: !!ok });
    } catch (e) {
      /* ignore */
    }
    const status = document.getElementById('reader-xrefs-save-status');
    if (status) {
      status.textContent = ok ? 'Saved privately on this device.' : 'That did not save—storage may be full. That is all right. Try again when you can.';
      setTimeout(() => {
        status.textContent = '';
      }, 3800);
    }
  });
}

function printReaderXrefsSheetBlock() {
  document.documentElement.classList.add('tdb-print-xrefs');
  const done = () => document.documentElement.classList.remove('tdb-print-xrefs');
  window.addEventListener('afterprint', done, { once: true });
  setTimeout(done, 90000);
  window.print();
}

function wireReaderXrefsSheetUiOnce() {
  const root = document.getElementById('reader-xrefs-layer');
  if (!root || root.dataset.tdbWired === '1') return;
  root.dataset.tdbWired = '1';
  const close = () => closeReaderCrossrefsSheet();
  const back = document.getElementById('reader-xrefs-back');
  const bd = document.getElementById('reader-xrefs-backdrop');
  if (back) back.addEventListener('click', close);
  if (bd) bd.addEventListener('click', close);
  const saveStudy = document.getElementById('reader-xrefs-save-mystudy');
  if (saveStudy) saveStudy.addEventListener('click', saveReaderXrefsToMyStudy);
  const wsOpen = document.getElementById('reader-xrefs-wordstudy-open');
  if (wsOpen) {
    wsOpen.addEventListener('click', () => {
      const r = readerXrefsLastAnchorRef;
      if (!r || !globalThis.TDBWordStudy || typeof globalThis.TDBWordStudy.open !== 'function') return;
      closeReaderCrossrefsSheet({ skipFocusRestore: true });
      globalThis.TDBWordStudy.open(r, readerXrefsLastVerseSnippet || '');
      try {
        trackEvent('reader_xrefs_open_wordstudy', { ok: true });
      } catch (e) {
        /* ignore */
      }
    });
  }
  const printBtn = document.getElementById('reader-xrefs-print');
  if (printBtn) printBtn.addEventListener('click', printReaderXrefsSheetBlock);
  const filterIn = document.getElementById('reader-xrefs-filter');
  if (filterIn) {
    filterIn.addEventListener('input', () => applyReaderXrefsFilter(filterIn.value));
  }
  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    if (root && !root.classList.contains('hidden')) close();
  });
  root.addEventListener('keydown', (ev) => {
    const panel = root.querySelector('.reader-sheet-panel');
    if (panel && !root.classList.contains('hidden')) tdbTrapDialogTabKeydown(ev, panel);
  });
}

function attachReaderVerseWordStudyControls() {
  const out = document.getElementById('reader-output');
  if (!out || !globalThis.TDBWordStudy || typeof globalThis.TDBWordStudy.open !== 'function') return;
  out.querySelectorAll('.context-line').forEach((line) => {
    if (line.querySelector('.reader-verse-wordstudy-btn')) return;
    const ref = line.dataset.ref;
    if (!ref) return;
    line.classList.add('reader-verse-line--tools');
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'reader-verse-wordstudy-btn';
    btn.setAttribute('aria-label', `Open verse study for ${ref}`);
    btn.setAttribute('title', 'Study this verse');
    btn.appendChild(document.createTextNode('Study this verse'));
    btn.addEventListener('click', (ev) => {
      ev.preventDefault();
      ev.stopPropagation();
      const txt = getVerseSnippetFromContextLine(line);
      globalThis.TDBWordStudy.open(ref, txt);
    });
    line.appendChild(btn);
  });
}

function wireReaderWordStudySheetUiOnce() {
  if (globalThis.TDBWordStudy && typeof globalThis.TDBWordStudy.init === 'function') {
    globalThis.TDBWordStudy.init();
  }
}
function maybeOpenReaderXrefFromQuery() {
  try {
    const params = new URLSearchParams(window.location.search || '');
    if (params.get('openXrefs') !== '1') return;
    const refRaw = params.get('ref') || '';
    const r = parseReference(refRaw) || String(refRaw).trim();
    if (!r) return;
    setTimeout(() => openReaderCrossrefsSheet(r, ''), 450);
  } catch (e) {
    /* ignore */
  }
}

const READER_CHAPTER_NOTES_KEY = 'tdb_reader_chapter_notes_v1';
var readerChapterNotesTimer = null;

function getReaderChapterNotesStorageKey(book, chapter) {
  return `${String(book || '').trim()}|${String(chapter || '').trim()}`;
}

function loadReaderChapterStudyNote(book, chapter) {
  const ta = document.getElementById('reader-chapter-study-notes');
  if (!ta) return;
  const key = getReaderChapterNotesStorageKey(book, chapter);
  if (!key || key === '|') {
    ta.value = '';
    return;
  }
  try {
    const o = JSON.parse(localStorage.getItem(READER_CHAPTER_NOTES_KEY) || '{}');
    ta.value = o && typeof o === 'object' && o[key] ? String(o[key]) : '';
  } catch (e) {
    ta.value = '';
  }
}

function saveReaderChapterStudyNote(book, chapter, text) {
  const key = getReaderChapterNotesStorageKey(book, chapter);
  if (!key || key === '|') return;
  try {
    let o = JSON.parse(localStorage.getItem(READER_CHAPTER_NOTES_KEY) || '{}');
    if (!o || typeof o !== 'object') o = {};
    const t = String(text || '').slice(0, 8000);
    if (t) o[key] = t;
    else delete o[key];
    localStorage.setItem(READER_CHAPTER_NOTES_KEY, JSON.stringify(o));
  } catch (e) {
    /* ignore quota */
  }
}

function wireReaderChapterStudyNotes() {
  const ta = document.getElementById('reader-chapter-study-notes');
  if (!ta || ta.dataset.tdbWiredStudy === '1') return;
  ta.dataset.tdbWiredStudy = '1';
  ta.addEventListener('input', () => {
    const book = document.getElementById('reader-book')?.value;
    const chapter = document.getElementById('reader-chapter')?.value;
    clearTimeout(readerChapterNotesTimer);
    const snapB = book;
    const snapC = chapter;
    readerChapterNotesTimer = setTimeout(() => {
      const b2 = document.getElementById('reader-book')?.value;
      const c2 = document.getElementById('reader-chapter')?.value;
      if (b2 === snapB && c2 === snapC) saveReaderChapterStudyNote(snapB, snapC, ta.value);
    }, 400);
  });
}

function applyReaderFromQuery() {
  const bookSelect = document.getElementById('reader-book');
  if (!bookSelect) return;
  const params = new URLSearchParams(window.location.search);
  const refParam = params.get('ref') || '';
  let book = params.get('book') || '';
  let chapter = params.get('chapter') || '';
  if (!book || !chapter) {
    const chapterKey = refParam ? getChapterKey(refParam) : null;
    const parsed = chapterKey ? parseChapterKey(chapterKey) : null;
    if (parsed) {
      book = parsed.book;
      chapter = parsed.chapter;
    }
  }
  if (book && chapter && bookIndex[book]) {
    selectReaderChapter(book, chapter, refParam);
  }
}

function applySearchFromQuery() {
  const params = new URLSearchParams(window.location.search);
  let value = params.get('q') || params.get('ref');
  if (!value) return;
  try {
    value = decodeURIComponent(value).trim().replace(/\s+/g, ' ');
  } catch {
    value = value.trim();
  }
  if (!value) return;
  const queryEl = getQueryInput();
  const searchBtn = document.getElementById('search-btn');
  if (!queryEl || !searchBtn) {
    var base = window.location.origin + (window.location.pathname || '/').replace(/\/[^/]*$/, '') || window.location.origin;
    if (!base.endsWith('/')) base += '/';
    window.location.href = base + 'index.html?q=' + encodeURIComponent(value);
    return;
  }
  queryEl.value = value;
  setView('search');
  if (typeof searchCache !== 'undefined' && searchCache.clear) searchCache.clear();
  const mainSearch = document.getElementById('main-search');
  if (mainSearch) tdbScrollIntoView(mainSearch, 'start', 'nearest');
  searchBtn.click();
}

function getRelatedRefs(ref, count = 3) {
  const chapterKey = getChapterKey(ref);
  if (!chapterKey || !chapterIndex[chapterKey]) return [];
  const verses = chapterIndex[chapterKey];
  const idx = verses.findIndex(v => v.ref === ref);
  if (idx === -1) return [];
  const half = Math.floor(count / 2);
  const start = Math.max(0, idx - half);
  const end = Math.min(verses.length - 1, idx + half);
  const out = [];
  for (let i = start; i <= end; i++) {
    if (verses[i].ref !== ref) out.push(verses[i].ref);
  }
  return out.slice(0, count);
}

function renderContextBlock(ref, radius = 3) {
  const chapterKey = getChapterKey(ref);
  if (!chapterKey || !chapterIndex[chapterKey]) return null;
  const verses = chapterIndex[chapterKey];
  const idx = verses.findIndex(v => v.ref === ref);
  if (idx === -1) return null;
  const start = Math.max(0, idx - radius);
  const end = Math.min(verses.length - 1, idx + radius);
  const container = document.createElement('div');
  container.className = 'context-block';
  for (let i = start; i <= end; i++) {
    const line = document.createElement('div');
    line.className = 'context-line';
    line.innerHTML = '<strong>' + escapeHtml(verses[i].ref) + '</strong> ' + escapeHtml(verses[i].text || '');
    container.appendChild(line);
  }
  return container;
}

