async function saveNoteToSupabase(note) {
  if (!canUseSupabase()) return note;
  const { data, error } = await supabaseClient
    .from('notes')
    .insert({ user_id: currentUserId, ref: note.ref, text: note.text })
    .select('id, ref, text')
    .single();
  if (error || !data) return note;
  return { id: data.id, ref: data.ref || note.ref, text: data.text || note.text };
}

async function deleteNoteFromSupabase(noteId) {
  if (!canUseSupabase() || !noteId) return;
  await supabaseClient.from('notes').delete().eq('id', noteId);
}

async function saveVerseToSupabase(verse) {
  if (!canUseSupabase()) return verse;
  const existing = await supabaseClient
    .from('saved_verses')
    .select('id')
    .eq('user_id', currentUserId)
    .eq('ref', verse.ref)
    .maybeSingle();
  if (existing.data?.id) return { ...verse, id: existing.data.id };

  const { data, error } = await supabaseClient
    .from('saved_verses')
    .insert({ user_id: currentUserId, ref: verse.ref, text: verse.text })
    .select('id, ref, text')
    .single();
  if (error || !data) return verse;
  return { id: data.id, ref: data.ref, text: data.text };
}

async function deleteVerseFromSupabase(verseId) {
  if (!canUseSupabase() || !verseId) return;
  await supabaseClient.from('saved_verses').delete().eq('id', verseId);
}

async function createCollectionToSupabase(name) {
  if (!canUseSupabase()) return null;
  const { data, error } = await supabaseClient
    .from('saved_collections')
    .insert({ user_id: currentUserId, name })
    .select('id, name')
    .single();
  if (error || !data) return null;
  return data;
}

async function saveCollectionItemToSupabase(collectionId, verse) {
  if (!canUseSupabase()) return verse;
  const existing = await supabaseClient
    .from('saved_verse_collections')
    .select('id')
    .eq('user_id', currentUserId)
    .eq('collection_id', collectionId)
    .eq('ref', verse.ref)
    .maybeSingle();
  if (existing.data?.id) return { ...verse, id: existing.data.id, collection_id: collectionId };

  const { data, error } = await supabaseClient
    .from('saved_verse_collections')
    .insert({ user_id: currentUserId, collection_id: collectionId, ref: verse.ref, text: verse.text })
    .select('id, ref, text, collection_id')
    .single();
  if (error || !data) return { ...verse, collection_id: collectionId };
  return { id: data.id, ref: data.ref, text: data.text, collection_id: data.collection_id };
}

/**
 * Save a verse ref + plain text into My Verses (default collection + optional Supabase).
 * Mirrors Search / Bible tool save path (savedCollectionItems).
 */
async function saveDailyVerseToMyVerses(refRaw, textRaw) {
  var ref = String(refRaw || '').replace(/\s*\(KJV\)\s*$/i, '').trim();
  var text = String(textRaw || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  if (!ref || !text) return { ok: false, reason: 'empty' };
  var collectionId = getActiveCollectionId();
  var existing = loadSavedCollectionItems().some(function (item) {
    return item.ref === ref && item.collection_id === collectionId;
  });
  if (existing) return { ok: true, already: true };
  try {
    var saved = await saveCollectionItemToSupabase(collectionId, { ref: ref, text: text });
    var next = loadSavedCollectionItems().filter(function (item) {
      return item.ref !== ref || item.collection_id !== collectionId;
    });
    next.unshift(Object.assign({}, saved, { collection_id: collectionId }));
    saveSavedCollectionItems(next);
    if (typeof renderSavedVerses === 'function' && document.getElementById('saved-verses')) {
      renderSavedVerses();
    }
    try {
      if (typeof window.dispatchEvent === 'function') {
        window.dispatchEvent(new CustomEvent('tdb-my-verses-updated'));
      }
    } catch (eMv) { /* non-fatal */ }
    if (typeof window.tdbRefreshHomeResume === 'function') window.tdbRefreshHomeResume();
    if (typeof showEliteToast === 'function') {
      showEliteToast('Saved to My Study — stays on your device.', { duration: 2000 });
    }
    return { ok: true, already: false };
  } catch (e) {
    return { ok: false, reason: 'error' };
  }
}
if (typeof window !== 'undefined') window.tdbSaveDailyVerseToMyVerses = saveDailyVerseToMyVerses;

function gatherLegacyTdbSavedNotes() {
  var merged = [];
  try {
    var main = JSON.parse(localStorage.getItem('tdb-saved-notes') || '[]');
    if (Array.isArray(main)) merged = merged.concat(main);
  } catch (_) {}
  try {
    for (var i = 0; i < localStorage.length; i++) {
      var k = localStorage.key(i);
      if (!k || k === 'tdb-saved-notes' || k.indexOf('tdb-saved-notes-') !== 0) continue;
      var extra = JSON.parse(localStorage.getItem(k) || '[]');
      if (Array.isArray(extra)) merged = merged.concat(extra);
    }
  } catch (_) {}
  var seen = {};
  var out = [];
  merged.forEach(function (n) {
    if (!n || !n.ref || !n.text) return;
    var ref = String(n.ref).replace(/\s*\(KJV\)\s*$/i, '').trim();
    var text = String(n.text || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    if (!ref || !text || seen[ref]) return;
    seen[ref] = true;
    out.push({ ref: ref, text: text });
  });
  return out;
}

function clearLegacyTdbSavedNotesKeys() {
  try {
    localStorage.setItem('tdb-saved-notes', '[]');
  } catch (_) {}
  try {
    var toRemove = [];
    for (var j = 0; j < localStorage.length; j++) {
      var key = localStorage.key(j);
      if (key && key.indexOf('tdb-saved-notes-') === 0) toRemove.push(key);
    }
    toRemove.forEach(function (rk) {
      try { localStorage.removeItem(rk); } catch (_) {}
    });
  } catch (_) {}
}

/**
 * Run after sync (signed-in) or on guest load — merges old tdb-saved-notes into My Verses, then clears legacy keys.
 */
async function migrateLegacyTdbSavedNotesOnce() {
  try {
    if (localStorage.getItem(TDB_SAVED_NOTES_MIGRATED_KEY) === '1') return;
    var legacy = gatherLegacyTdbSavedNotes();
    if (!legacy.length) {
      localStorage.setItem(TDB_SAVED_NOTES_MIGRATED_KEY, '1');
      return;
    }
    ensureDefaultCollection();
    for (var i = 0; i < legacy.length; i++) {
      await saveDailyVerseToMyVerses(legacy[i].ref, legacy[i].text);
    }
    clearLegacyTdbSavedNotesKeys();
    localStorage.setItem(TDB_SAVED_NOTES_MIGRATED_KEY, '1');
    if (typeof trackEvent === 'function') trackEvent('tdb_saved_notes_migrated', { count: legacy.length });
    if (typeof renderSavedVerses === 'function') renderSavedVerses();
  } catch (e) {
    if (typeof console !== 'undefined' && console.warn) console.warn('TDB: saved-notes migration skipped', e);
  }
}

/** Verse journal / export: My Verses first, then any unmigrated legacy notes (deduped by ref). */
function gatherVersesForJournalExport() {
  var seen = {};
  var out = [];
  function add(ref, text) {
    var r = String(ref || '').replace(/\s*\(KJV\)\s*$/i, '').trim();
    var t = String(text || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    if (!r || !t || seen[r]) return;
    seen[r] = true;
    out.push({ ref: r, text: t });
  }
  try {
    var items = JSON.parse(localStorage.getItem(SAVED_COLLECTION_ITEMS_KEY) || '[]');
    if (Array.isArray(items)) items.forEach(function (it) { if (it && it.ref && it.text) add(it.ref, it.text); });
  } catch (_) {}
  gatherLegacyTdbSavedNotes().forEach(function (n) { add(n.ref, n.text); });
  return out;
}
if (typeof window !== 'undefined') window.tdbGatherVersesForJournalExport = gatherVersesForJournalExport;

