function queryLooksSeasonal(queryText, activeTopics) {
  var blob = normalizeInput([queryText].concat(activeTopics || []).join(' '));
  return HOME_SEARCH_SEASONAL_QUERY.test(blob);
}

function pickPreferredHomeSearchPlans(library, activeTopics, limit) {
  var picked = [];
  var seen = {};
  (activeTopics || []).forEach(function (topic) {
    var prefs = HOME_SEARCH_TOPIC_PLAN_PREFS[topic];
    if (!prefs) return;
    prefs.forEach(function (id) {
      if (picked.length >= limit || seen[id]) return;
      var match = (library || []).find(function (entry) { return entry.id === id; });
      if (match) {
        seen[id] = 1;
        picked.push(match);
      }
    });
  });
  return picked;
}

function pickHomeSearchEntries(library, results, queryText, limit, fallbackIds) {
  var activeTopics = getHomeSearchActiveTopics(results, queryText);
  var queryTokens = getHomeSearchQueryTokens(queryText);
  var seasonalOk = queryLooksSeasonal(queryText, activeTopics);
  var preferred = pickPreferredHomeSearchPlans(library, activeTopics, limit);
  if (preferred.length >= limit) return preferred.slice(0, limit);
  var ranked = (library || []).map(function (entry) {
    var seasonal = !!(entry && HOME_SEARCH_SEASONAL_PLAN_IDS[entry.id]);
    var score = scoreHomeSearchEntry(entry, activeTopics, queryTokens);
    if (seasonal && !seasonalOk) score = 0;
    return { entry: entry, score: score };
  }).sort(function (a, b) {
    if (b.score !== a.score) return b.score - a.score;
    return String(a.entry.title || '').localeCompare(String(b.entry.title || ''));
  });
  var picked = preferred.slice();
  ranked.filter(function (row) { return row.score > 0; }).forEach(function (row) {
    if (picked.length >= limit) return;
    if (picked.indexOf(row.entry) === -1) picked.push(row.entry);
  });
  if (picked.length < limit && Array.isArray(fallbackIds)) {
    fallbackIds.forEach(function (id) {
      if (picked.length >= limit) return;
      var match = (library || []).find(function (entry) { return entry.id === id; });
      if (match && picked.indexOf(match) === -1) picked.push(match);
    });
  }
  return picked.slice(0, limit);
}

function buildHomeSearchPlanMatches(results, queryText) {
  var q = normalizeInput(String(queryText || ''));
  var jesusSaid = q === 'jesus said' || q === 'red letter' || q === 'words of jesus' || (results && results.intent === 'jesus_said');
  var active = getHomeSearchActiveTopics(results, queryText);
  var primary = active[0] || '';
  var prefs = HOME_SEARCH_TOPIC_PLAN_PREFS[q] || HOME_SEARCH_TOPIC_PLAN_PREFS[primary] || null;
  /* Verse lookup: only plans that actually score (e.g. Gospel of John for John 3:16).
     Never pad with leftover comfort/peace plans. */
  if (results && results.intent === 'reference') {
    return pickHomeSearchEntries(HOME_SEARCH_PLAN_LIBRARY, results, queryText, 2, []);
  }
  /* “Who was Ruth?” is a person, not a leftover purpose/trauma lane. */
  if (results && results.usedCuratedKnowledge) {
    return pickHomeSearchEntries(HOME_SEARCH_PLAN_LIBRARY, results, queryText, 1, []);
  }
  return pickHomeSearchEntries(
    HOME_SEARCH_PLAN_LIBRARY,
    results,
    queryText,
    3,
    jesusSaid ? ['hisownwords', 'comeuntome', 'gospeljohn'] : (prefs || ['psalmscomfort', 'peace', 'hopeuncertain'])
  );
}

function buildHomeSearchResourceMatches(results, queryText) {
  if (results && results.usedCuratedKnowledge) return [];
  return pickHomeSearchEntries(
    HOME_SEARCH_RESOURCE_LIBRARY,
    results,
    queryText,
    3,
    []
  );
}

function stripHtmlToPlainText(text) {
  return String(text || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

function truncateWords(text, maxWords) {
  var words = stripHtmlToPlainText(text).split(/\s+/).filter(Boolean);
  if (!words.length) return '';
  if (!maxWords || words.length <= maxWords) return words.join(' ');
  return words.slice(0, maxWords).join(' ') + '...';
}

function buildHomeSearchHighlightRegex(queryText) {
  var tokens = getHomeSearchQueryTokens(queryText);
  if (!tokens.length) return null;
  var uniq = uniqueList(tokens).sort(function (a, b) { return b.length - a.length; });
  if (!uniq.length) return null;
  try {
    return new RegExp('(' + uniq.map(function (token) { return escapeRegExp(token); }).join('|') + ')', 'ig');
  } catch (_) {
    return null;
  }
}

function appendHighlightedText(el, text, regex) {
  if (!el) return;
  var value = String(text || '');
  el.textContent = '';
  if (!regex || !value) {
    el.textContent = value;
    return;
  }
  regex.lastIndex = 0;
  var lastIndex = 0;
  var match;
  while ((match = regex.exec(value))) {
    if (match.index > lastIndex) {
      el.appendChild(document.createTextNode(value.slice(lastIndex, match.index)));
    }
    var mark = document.createElement('mark');
    mark.className = 'home-search-highlight';
    mark.textContent = match[0];
    el.appendChild(mark);
    lastIndex = match.index + match[0].length;
    if (match[0].length === 0) regex.lastIndex += 1;
  }
  if (lastIndex < value.length) {
    el.appendChild(document.createTextNode(value.slice(lastIndex)));
  }
}

function getHomeSearchNextStepTeaser(verse) {
  var ctx = verse && verse.ref && typeof getVerseContext === 'function' ? getVerseContext(verse.ref) : null;
  var line = ctx && ctx.application ? String(ctx.application).trim() : '';
  if (!line && verse && verse.plain_meaning) line = String(verse.plain_meaning).trim();
  if (!line) line = 'Stay with this verse for one slow minute, then take the next faithful step in front of you.';
  if (line.length > 110) line = line.slice(0, 107).replace(/\s+\S*$/, '') + '...';
  return line;
}

function getHomeSearchPrayerText(verse) {
  var ctx = verse && verse.ref && typeof getVerseContext === 'function' ? getVerseContext(verse.ref) : null;
  var prayer = ctx && ctx.prayer ? String(ctx.prayer).trim() : '';
  if (!prayer) prayer = buildPrayerFromVerse(verse.ref, stripHtmlToPlainText(verse.text || ''));
  if (prayer.length > 170) prayer = prayer.slice(0, 167).replace(/\s+\S*$/, '') + '...';
  return prayer;
}

var lastHomeAskTheWordResponse = { key: '', data: null };

function getHomeAskTheWordKey(queryText) {
  return normalizeInput(String(queryText || ''));
}

function dedupeStickyWayfindBars() {
  var bars = document.querySelectorAll('.tdb-sticky-wayfind');
  if (!bars || bars.length <= 1) return;
  for (var i = 1; i < bars.length; i += 1) {
    var extra = bars[i];
    if (extra && extra.parentNode) extra.parentNode.removeChild(extra);
  }
}

(function wireHomeWayfindToggle() {
  var toggle = document.getElementById('tdb-wayfind-toggle');
  var bar = document.getElementById('tdb-sticky-wayfind');
  if (!toggle || !bar) return;

  function syncForViewport() {
    var mobile = window.matchMedia && window.matchMedia('(max-width: 899px)').matches;
    if (!mobile) {
      bar.classList.remove('is-open');
      toggle.setAttribute('aria-expanded', 'false');
      return;
    }
    if (!bar.classList.contains('is-open')) {
      toggle.setAttribute('aria-expanded', 'false');
    }
  }

  toggle.addEventListener('click', function () {
    var mobile = window.matchMedia && window.matchMedia('(max-width: 899px)').matches;
    if (!mobile) return;
    var next = !bar.classList.contains('is-open');
    bar.classList.toggle('is-open', next);
    toggle.setAttribute('aria-expanded', next ? 'true' : 'false');
  });

  window.addEventListener('resize', syncForViewport, { passive: true });
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', syncForViewport);
  else syncForViewport();
})();

function setHomeAskTheWordResponse(queryText, data) {
  lastHomeAskTheWordResponse = {
    key: getHomeAskTheWordKey(queryText),
    data: data || null
  };
}

function getHomeAskTheWordResponse(queryText) {
  var key = getHomeAskTheWordKey(queryText);
  if (!key || !lastHomeAskTheWordResponse || lastHomeAskTheWordResponse.key !== key) return null;
  return lastHomeAskTheWordResponse.data || null;
}

function clearHomeAskTheWordResponse(queryText) {
  if (!queryText || lastHomeAskTheWordResponse.key === getHomeAskTheWordKey(queryText)) {
    lastHomeAskTheWordResponse = { key: '', data: null };
  }
}

function getAskTheWordTokenCount(queryText) {
  return normalizeInput(String(queryText || '')).split(/\s+/).filter(Boolean).length;
}

function isAskTheWordSingleWordTopic(queryText, results) {
  var count = getAskTheWordTokenCount(queryText);
  if (count !== 1) return false;
  var normalized = getHomeAskTheWordKey(queryText);
  return !!(
    normalized &&
    (
      (results && results.intent === 'topic') ||
      (results && results.semanticTopic) ||
      (typeof resolveTopicFromToken === 'function' && resolveTopicFromToken(normalized))
    )
  );
}

function getAskTheWordHeading(queryText, results, response) {
  if (isAskTheWordSingleWordTopic(queryText, results)) {
    return 'Verses about ' + titleCaseHomeTopic(getHomeSearchDisplayQuery(queryText) || queryText || '');
  }
  if (response && response.answer_mode === 'key_scriptures') {
    return 'Key Scriptures';
  }
  if (response && response.answer_mode === 'closest_principles') {
    return 'Closest Scriptural anchors';
  }
  return 'Verses that meet you here';
}

function buildAskTheWordLocalLead(queryText, results) {
  var profile = typeof classifyAskTheWordQuery === 'function' ? classifyAskTheWordQuery(queryText) : null;
  if (profile && profile.offTopic && profile.fallbackLead) {
    return profile.fallbackLead;
  }
  // When a curated answer will render below, keep the header lead short.
  if (typeof findBiblicalAnswer === 'function' && findBiblicalAnswer(queryText)) {
    return 'A short Bible answer sits below, then the verses. Stay with what Scripture says.';
  }
  if (profile && profile.fallbackLead && (profile.kind === 'knowledge' || profile.kind === 'say_about')) {
    return profile.fallbackLead;
  }
  var heartfelt = typeof getHeartfeltMessageForQuery === 'function' ? getHeartfeltMessageForQuery(queryText, results) : '';
  if (isAskTheWordSingleWordTopic(queryText, results)) {
    var title = getAskTheWordHeading(queryText, results);
    return heartfelt
      ? (title + '. ' + heartfelt)
      : (title + '. God meets real life with real truth. Start with these KJV verses.');
  }
  if (heartfelt) return heartfelt + ' The Bible does not turn away. Start with these KJV verses.';
  if (profile && profile.fallbackLead) return profile.fallbackLead;
  return 'This moment is real. Scripture meets it plainly. Start with these KJV verses.';
}

function buildAskTheWordFooterCopy(queryText, results) {
  if (isAskTheWordSingleWordTopic(queryText, results)) {
    return 'What stays with you here?';
  }
  return 'What lingers after you read? Bring that to the Lord plainly.';
}

function getAskTheWordSources(queryText, results, response) {
  if (response && Array.isArray(response.sources) && response.sources.length) return response.sources.slice(0, 6);
  if (results && Array.isArray(results.verses) && results.verses.length) {
    return results.verses.slice(0, 6).map(function (verse) { return verse && verse.ref; }).filter(Boolean);
  }
  return [];
}

function shouldFetchHomeQa(queryText, parsed) {
  var raw = String(queryText || '').trim();
  if (!raw) return false;
  if (typeof classifyAskTheWordQuery === 'function') {
    var offHome = classifyAskTheWordQuery(raw);
    if (offHome && offHome.offTopic) return false;
  }
  if (parsed && parsed.intent === 'reference') return false;
  if (raw.indexOf('?') !== -1) return true;
  var normalized = normalizeInput(raw);
  var tokenCount = normalized.split(/\s+/).filter(Boolean).length;
  if (tokenCount >= 3) return true;
  if (tokenCount === 1 && typeof resolveTopicFromToken === 'function' && resolveTopicFromToken(normalized)) return false;
  return /\b(i|im|i'm|me|my|mine|boss|coworker|colleague|marriage|family|kids|angry|anger|exhausted|tired|toxic|doubt|forgive|grief|hurt|hurting|work|why|how|what|who|when)\b/i.test(raw);
}

function getHomeSearchDetailHost(output) {
  if (!output) return null;
  var host = output.querySelector('.home-search-detail-host');
  if (host) return host;
  host = document.createElement('div');
  host.className = 'home-search-detail-host';
  host.hidden = true;
  output.appendChild(host);
  return host;
}

function clearHomeSearchDetail(output) {
  var host = getHomeSearchDetailHost(output);
  if (!host) return;
  host.hidden = true;
  host.textContent = '';
}

function updateHomeSearchSaveButton(button, verse) {
  if (!button || !verse || !verse.ref) return;
  var exists = loadSavedCollectionItems().some(function (item) {
    return item && item.ref === verse.ref;
  });
  if (exists) {
    button.textContent = 'Saved';
    button.disabled = true;
    button.setAttribute('aria-label', verse.ref + ' is already in My Study');
  } else {
    button.textContent = 'Save to My Study';
    button.disabled = false;
    button.setAttribute('aria-label', 'Save ' + verse.ref + ' to My Study on this device');
  }
}

function buildHomeSearchInfoAccordion(summaryText, rows, href) {
  var details = document.createElement('details');
  details.className = 'home-search-accordion';
  var summary = document.createElement('summary');
  summary.textContent = summaryText;
  details.appendChild(summary);
  var body = document.createElement('div');
  body.className = 'home-search-accordion-body';
  if (Array.isArray(rows) && rows.length) {
    var list = document.createElement('ul');
    list.className = 'home-search-accordion-list';
    rows.forEach(function (row) {
      if (!row || !row.label || !row.value) return;
      var li = document.createElement('li');
      var strong = document.createElement('strong');
      strong.textContent = row.label + ' ';
      li.appendChild(strong);
      li.appendChild(document.createTextNode(String(row.value)));
      list.appendChild(li);
    });
    body.appendChild(list);
  }
  if (href) {
    var link = document.createElement('a');
    link.className = 'home-search-inline-link';
    link.href = href;
    link.textContent = 'Open the full chapter';
    body.appendChild(link);
  }
  details.appendChild(body);
  return details;
}

function renderHomeSearchDetail(output, verse, queryText) {
  if (!output || !verse || !verse.ref) return;
  var host = getHomeSearchDetailHost(output);
  if (!host) return;
  host.hidden = false;
  host.textContent = '';

  var panel = document.createElement('article');
  panel.className = 'home-search-detail-panel';
  panel.setAttribute('aria-label', 'Verse for ' + verse.ref);
  panel.setAttribute('data-tdb-no-verse-breakdown', '1');

  var topActions = document.createElement('div');
  topActions.className = 'home-search-detail-top-actions';

  var backTop = document.createElement('button');
  backTop.type = 'button';
  backTop.className = 'btn btn-secondary home-search-back-btn';
  backTop.textContent = 'Back to results';
  backTop.addEventListener('click', function () {
    clearHomeSearchDetail(output);
    tdbScrollIntoView(output, 'start', 'nearest');
  });
  topActions.appendChild(backTop);
  panel.appendChild(topActions);

  /* Same KISS stack as list cards — not a second full breakdown maze. */
  var detailText = stripHtmlToPlainText(verse.text || '');
  var detailRef = String(verse.ref || '').replace(/\s*\(KJV\)\s*$/i, '').trim();
  if (
    !detailText ||
    detailText.replace(/[“”"']/g, '').replace(/\s*\(KJV\)\s*$/i, '').trim().toLowerCase() === detailRef.toLowerCase()
  ) {
    detailText =
      (typeof getBibleVerseText === 'function' ? getBibleVerseText(detailRef) : '') ||
      (bible && bible[detailRef]) ||
      detailText;
    detailText = stripHtmlToPlainText(detailText || '');
  }
  var kissDetail = null;
  try {
    var kissBuild =
      (window.TDBBbeSimple && typeof window.TDBBbeSimple.buildKissVerseCard === 'function'
        ? window.TDBBbeSimple.buildKissVerseCard
        : null) ||
      (typeof window.TDB_buildKissVerseCard === 'function' ? window.TDB_buildKissVerseCard : null);
    if (kissBuild) {
      kissDetail = kissBuild({
        ref: verse.ref,
        text: detailText,
        className: 'home-search-detail-kiss'
      });
    }
  } catch (eKissDet) {
    kissDetail = null;
  }
  if (kissDetail) {
    panel.appendChild(kissDetail);
  } else {
    var verseSection = document.createElement('section');
    verseSection.className = 'home-search-detail-section home-search-detail-section--verse';
    var verseRef = document.createElement('p');
    verseRef.className = 'home-search-detail-ref';
    verseRef.textContent = verse.ref + ' (KJV)';
    verseSection.appendChild(verseRef);
    var verseBody = document.createElement('p');
    verseBody.className = 'home-search-detail-text';
    verseBody.textContent = detailText;
    verseSection.appendChild(verseBody);
    panel.appendChild(verseSection);
  }

  var nextStepSection = document.createElement('section');
  nextStepSection.className = 'home-search-detail-section';
  var nextStepHeading = document.createElement('h3');
  nextStepHeading.className = 'home-search-detail-heading';
  nextStepHeading.textContent = 'One small step';
  nextStepSection.appendChild(nextStepHeading);
  var nextStepBody = document.createElement('p');
  nextStepBody.className = 'home-search-detail-copy';
  nextStepBody.textContent = getHomeSearchNextStepTeaser(verse);
  nextStepSection.appendChild(nextStepBody);
  panel.appendChild(nextStepSection);

  var prayerSection = document.createElement('section');
  prayerSection.className = 'home-search-detail-section';
  var prayerHeading = document.createElement('h3');
  prayerHeading.className = 'home-search-detail-heading';
  prayerHeading.textContent = 'A simple prayer';
  prayerSection.appendChild(prayerHeading);
  var prayerBody = document.createElement('p');
  prayerBody.className = 'home-search-detail-copy';
  prayerBody.textContent = getHomeSearchPrayerText(verse);
  prayerSection.appendChild(prayerBody);
  panel.appendChild(prayerSection);

  host.appendChild(panel);
  tdbScrollIntoView(host, 'start', 'nearest');
  return;

  /* Legacy accordion path below kept unreachable for safety if someone rewires later. */
  var accordions = document.createElement('div');
  accordions.className = 'home-search-accordions';

  var relatedRefs = typeof getRelatedRefs === 'function' ? getRelatedRefs(verse.ref, 3) : [];
  if (relatedRefs && relatedRefs.length) {
    var relatedDetails = document.createElement('details');
    relatedDetails.className = 'home-search-accordion';
    var relatedSummary = document.createElement('summary');
    relatedSummary.textContent = 'Related verses';
    relatedDetails.appendChild(relatedSummary);
    var relatedBody = document.createElement('div');
    relatedBody.className = 'home-search-accordion-body';
    var relatedList = document.createElement('div');
    relatedList.className = 'home-search-related-list';
    relatedRefs.forEach(function (ref) {
      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'home-search-related-btn';
      btn.textContent = ref;
      btn.addEventListener('click', function () {
        if (typeof window.runSearchWithInput === 'function') window.runSearchWithInput(ref);
      });
      relatedList.appendChild(btn);
    });
    relatedBody.appendChild(relatedList);
    relatedDetails.appendChild(relatedBody);
    accordions.appendChild(relatedDetails);
  }

  var ctx = verse.ref && typeof getVerseContext === 'function' ? getVerseContext(verse.ref) : null;
  var plainMeaning = typeof getPlainMeaning === 'function' ? getPlainMeaning(verse.ref) : '';
  var contextRows = [];
  if (ctx && ctx.speaker) contextRows.push({ label: 'Speaker:', value: ctx.speaker });
  if (ctx && ctx.audience) contextRows.push({ label: 'To whom:', value: ctx.audience });
  if (plainMeaning) contextRows.push({ label: 'Plain words:', value: plainMeaning });
  if (ctx && ctx.application) contextRows.push({ label: 'Today:', value: ctx.application });
  if (contextRows.length) {
    accordions.appendChild(buildHomeSearchInfoAccordion('Word study / context', contextRows, ''));
  }

  accordions.appendChild(buildHomeSearchInfoAccordion('Full chapter link', [], buildReaderUrl(verse.ref)));
  panel.appendChild(accordions);

  var bottomActions = document.createElement('div');
  bottomActions.className = 'home-search-detail-bottom-actions';
  var backBottom = document.createElement('button');
  backBottom.type = 'button';
  backBottom.className = 'btn btn-secondary home-search-back-btn';
  backBottom.textContent = 'Back to results';
  backBottom.addEventListener('click', function () {
    clearHomeSearchDetail(output);
    tdbScrollIntoView(output, 'start', 'nearest');
  });
  bottomActions.appendChild(backBottom);
  panel.appendChild(bottomActions);

  host.appendChild(panel);
  tdbScrollIntoView(host, 'start', 'nearest');
}

function buildHomeSearchCountLine(results, planMatches, resourceMatches, queryText) {
  var parts = [];
  var verseCount = results && Array.isArray(results.verses) ? results.verses.length : 0;
  if (verseCount) parts.push(verseCount + ' verse' + (verseCount === 1 ? '' : 's'));
  if (planMatches.length) parts.push(planMatches.length + ' Battle Plan' + (planMatches.length === 1 ? '' : 's'));
  if (resourceMatches.length) parts.push(resourceMatches.length + ' journal/topic door' + (resourceMatches.length === 1 ? '' : 's'));
  var displayQuery = getHomeSearchDisplayQuery(queryText);
  if (!parts.length) return displayQuery ? ('Search results for "' + displayQuery + '"') : 'Search results';
  return parts.join(' • ') + (displayQuery ? (' for "' + displayQuery + '"') : '');
}

function setHomeSearchSectionFilter(output, filterValue) {
  if (!output) return;
  var cards;
  var i;
  var sections = output.querySelectorAll('[data-home-search-section]');
  for (i = 0; i < sections.length; i++) {
    var section = sections[i];
    var show = filterValue === 'all' || section.getAttribute('data-home-search-section') === filterValue;
    section.hidden = !show;
  }
  if (filterValue !== 'all' && filterValue !== 'verses') {
    clearHomeSearchDetail(output);
  }
  cards = output.querySelectorAll('.home-search-filter-chip[data-filter-kind="section"]');
  for (i = 0; i < cards.length; i++) {
    var chip = cards[i];
    var active = chip.getAttribute('data-filter-value') === filterValue;
    chip.setAttribute('aria-pressed', active ? 'true' : 'false');
    chip.classList.toggle('is-active', active);
  }
}

function buildHomeSearchFilterRow(output, availableSections, activeTopics) {
  var wrap = document.createElement('div');
  wrap.className = 'home-search-filter-row';

  if (availableSections.length > 1) {
    ['all'].concat(availableSections).forEach(function (sectionKey) {
      var chip = document.createElement('button');
      chip.type = 'button';
      chip.className = 'home-search-filter-chip';
      chip.setAttribute('data-filter-kind', 'section');
      chip.setAttribute('data-filter-value', sectionKey);
      chip.setAttribute('aria-pressed', sectionKey === 'all' ? 'true' : 'false');
      if (sectionKey === 'all') chip.classList.add('is-active');
      chip.textContent = sectionKey === 'all'
        ? 'All'
        : sectionKey === 'verses'
          ? 'Verses'
          : sectionKey === 'plans'
            ? 'Plans'
            : 'Journal / Topics';
      chip.addEventListener('click', function () {
        setHomeSearchSectionFilter(output, sectionKey);
      });
      wrap.appendChild(chip);
    });
  }

  activeTopics.slice(0, 4).forEach(function (topic) {
    var chip = document.createElement('button');
    chip.type = 'button';
    chip.className = 'home-search-filter-chip home-search-filter-chip--topic';
    chip.textContent = titleCaseHomeTopic(topic);
    chip.setAttribute('aria-label', 'Refine this search to ' + titleCaseHomeTopic(topic));
    chip.addEventListener('click', function () {
      if (typeof window.runSearchWithInput === 'function') window.runSearchWithInput(topic);
    });
    wrap.appendChild(chip);
  });

  return wrap;
}

function buildHomeVerseCard(output, verse, queryText) {
  var plainVerse = stripHtmlToPlainText(verse.text || '');
  var verseText = plainVerse;

  var plainMeaning = typeof getPlainMeaning === 'function' ? getPlainMeaning(verse.ref) : '';
  if (!plainMeaning && typeof getVerseBreakdown === 'function') {
    var autoBd = getVerseBreakdown(verse.ref, verseText, null);
    if (autoBd) {
      plainMeaning = String(
        autoBd.plainMeaningOnly || autoBd.layman || autoBd.plainExplanation || ''
      ).trim();
    }
  }
  if (typeof window.TDBTeachingQuality !== 'undefined' && window.TDBTeachingQuality.meaningOnly) {
    plainMeaning = window.TDBTeachingQuality.meaningOnly(plainMeaning) || plainMeaning;
  } else {
    plainMeaning = String(plainMeaning || '')
      .replace(/^What was going on:[\s\S]*?What it means:\s*/i, '')
      .replace(/^What it means:\s*/i, '')
      .trim();
  }
  if (
    /^In plain terms for life today:/i.test(plainMeaning) ||
    /Sit with that until one phrase lands/i.test(plainMeaning)
  ) {
    plainMeaning = '';
  }

  /* Resolve real KJV body — never show the reference string as the verse. */
  var refBare = String(verse.ref || '').replace(/\s*\(KJV\)\s*$/i, '').replace(/\s+/g, ' ').trim();
  var textLooksLikeRef =
    !plainVerse ||
    plainVerse.replace(/[“”"']/g, '').replace(/\s*\(KJV\)\s*$/i, '').replace(/\s+/g, ' ').trim().toLowerCase() ===
      refBare.toLowerCase() ||
    /^[1-3]?\s*[A-Za-z][A-Za-z\s.]+\s+\d+:\d+(-\d+)?$/i.test(plainVerse.replace(/[“”"']/g, '').trim());
  if (textLooksLikeRef) {
    var resolved =
      (typeof getBibleVerseText === 'function' ? getBibleVerseText(refBare) : '') ||
      (bible && (bible[refBare] || bible[refBare.replace(/^Psalms\s+/i, 'Psalm ')] || bible[refBare.replace(/^Psalm\s+/i, 'Psalms ')])) ||
      '';
    if (resolved) {
      plainVerse = stripHtmlToPlainText(resolved);
      verseText = plainVerse;
    }
  }

  /* KISS stack only: KJV → BBE → context. No heavy inline “Verse breakdown” chrome. */
  var card = null;
  try {
    var kissBuild =
      (window.TDBBbeSimple && typeof window.TDBBbeSimple.buildKissVerseCard === 'function'
        ? window.TDBBbeSimple.buildKissVerseCard
        : null) ||
      (typeof window.TDB_buildKissVerseCard === 'function' ? window.TDB_buildKissVerseCard : null);
    if (kissBuild) {
      card = kissBuild({
        ref: verse.ref,
        text: plainVerse,
        plain: plainMeaning,
        className: 'tdb-kiss-verse home-search-card home-search-card--verse tdb-result-card'
      });
    }
  } catch (eKissHome) {
    card = null;
  }
  if (!card) {
    card = document.createElement('article');
    card.className = 'tdb-kiss-verse home-search-card home-search-card--verse tdb-result-card';
    var ref = document.createElement('p');
    ref.className = 'home-search-card-ref tdb-kiss-verse__ref';
    ref.textContent = verse.ref;
    card.appendChild(ref);
    var versePreview = document.createElement('p');
    versePreview.className = 'home-search-card-copy tdb-kiss-verse__kjv';
    versePreview.textContent = plainVerse ? ('\u201c' + plainVerse + '\u201d') : '';
    card.appendChild(versePreview);
    if (plainMeaning) {
      var primary = document.createElement('div');
      primary.className = 'tdb-kiss-verse__block';
      var meanLab = document.createElement('h4');
      meanLab.className = 'tdb-kiss-verse__label';
      meanLab.textContent = 'What it means';
      var meanP = document.createElement('p');
      meanP.className = 'tdb-kiss-verse__mean';
      meanP.textContent = plainMeaning;
      primary.appendChild(meanLab);
      primary.appendChild(meanP);
      card.appendChild(primary);
    }
  }
  card.setAttribute('data-home-result-card', 'verse');
  card.setAttribute('data-tdb-kiss-verse', '1');
  card.setAttribute('data-tdb-no-verse-breakdown', '1');
  card.setAttribute('data-ref', refBare);
  if (plainVerse) card.setAttribute('data-verse-text', plainVerse);

  /* Quiet actions only — no dual breakdown / kid-teen-adult wall. */
  var actionBar = document.createElement('div');
  actionBar.className = 'ask-word-action-bar tdb-kiss-verse__actions';

  function buildActionGroup(label) {
    var group = document.createElement('div');
    group.className = 'ask-word-action-group';
    group.setAttribute('role', 'group');
    group.setAttribute('aria-label', label);
    return group;
  }

  function buildActionButton(text, ariaLabel, onClick) {
    var button = document.createElement('button');
    button.type = 'button';
    button.className = 'btn btn-secondary ask-word-action-btn';
    button.textContent = text;
    button.setAttribute('aria-label', ariaLabel);
    button.addEventListener('click', onClick);
    return button;
  }

  function readerShareUrl() {
    try {
      return new URL(buildReaderUrl(verse.ref), window.location.origin).href;
    } catch (_) {
      return window.location.href;
    }
  }

  var quietGroup = buildActionGroup('Actions');
  quietGroup.appendChild(buildActionButton('Copy', 'Copy ' + verse.ref, function () {
    if (!navigator.clipboard) return;
    navigator.clipboard.writeText(verse.ref + ': ' + verseText).catch(function () {});
  }));
  quietGroup.appendChild(buildActionButton('Listen', 'Listen to ' + verse.ref, function () {
    speakVerse(verse.ref, verseText);
  }));
  quietGroup.appendChild(buildActionButton('Save', 'Save ' + verse.ref + ' to My Study', function (event) {
    var btn = event.currentTarget;
    if (btn.disabled) return;
    btn.disabled = true;
    saveDailyVerseToMyVerses(verse.ref, verseText).then(function () {
      btn.textContent = 'Saved';
      setTimeout(function () { btn.textContent = 'Save'; btn.disabled = false; }, 1600);
    }).catch(function () {
      btn.disabled = false;
      btn.textContent = 'Try again';
      setTimeout(function () { btn.textContent = 'Save'; }, 1800);
    });
  }));
  quietGroup.appendChild(buildActionButton('Chapter', 'Open full chapter for ' + verse.ref, function () {
    window.location.href = buildReaderUrl(verse.ref);
  }));
  actionBar.appendChild(quietGroup);

  card.appendChild(actionBar);

  return card;
}

function buildHomeLinkCard(entry, sectionType) {
  var card = document.createElement('article');
  card.className = 'home-search-card home-search-card--link';
  card.setAttribute('data-home-result-card', sectionType);

  var meta = document.createElement('div');
  meta.className = 'home-search-link-meta';
  var badge = document.createElement('span');
  badge.className = 'home-search-link-badge';
  badge.textContent = sectionType === 'plans'
    ? ((entry.featured ? 'Best fit · ' : '') + ((entry.days || 7) + ' days'))
    : (entry.kind || 'Link');
  meta.appendChild(badge);
  card.appendChild(meta);

  var title = document.createElement('h4');
  title.className = 'home-search-link-title';
  var link = document.createElement('a');
  link.href = entry.href;
  link.textContent = entry.title;
  title.appendChild(link);
  card.appendChild(title);

  var desc = document.createElement('p');
  desc.className = 'home-search-card-teaser';
  desc.textContent = entry.description;
  card.appendChild(desc);

  if (entry.matchNote) {
    var note = document.createElement('p');
    note.className = 'home-search-note';
    note.textContent = entry.matchNote;
    card.appendChild(note);
  }

  return card;
}

function appendSearchBpIf(parent, label, text, extraClass) {
  var t = String(text || '').trim();
  if (!t || !parent) return;
  var div = document.createElement('div');
  div.className = 'day-bp search-vbd-bp' + (extraClass ? ' ' + extraClass : '');
  var pl = document.createElement('p');
  pl.className = 'day-bp-label';
  pl.textContent = label;
  var pt = document.createElement('p');
  pt.className = 'day-bp-text';
  pt.textContent = t;
  div.appendChild(pl);
  div.appendChild(pt);
  parent.appendChild(div);
}

function attachHomeSearchDigDeeper(verse, verseText) {
  var vbStd = window.TDB_verseBreakdownStandard;
  if (!vbStd || typeof vbStd.hydrateAskTheTeacherDigDeeper !== 'function' || !verse || !verse.ref) return null;

  var digDet = document.createElement('div');
  digDet.className = 'tdb-dig-deeper tdb-dig-deeper--always-open';
  digDet.setAttribute('data-tdb-dig-always-open', '1');
  var digHeading = document.createElement('h3');
  digHeading.className = 'tdb-dig-deeper__always-heading';
  digHeading.textContent = 'More from the Word';
  digDet.appendChild(digHeading);

  var digContent = document.createElement('div');
  digContent.className = 'tdb-dig-deeper__content';
  var digDeep = document.createElement('div');
  digDeep.className = 'search-breakdown-deep';

  var ctx = typeof getVerseContext === 'function' ? getVerseContext(verse.ref) : null;
  appendSearchBpIf(digDeep, 'Who\u2019s speaking', ctx && ctx.speaker);
  appendSearchBpIf(digDeep, 'To whom', ctx && ctx.audience);
  appendSearchBpIf(digDeep, 'Word study / today', ctx && ctx.application);

  if (typeof buildReaderUrl === 'function') {
    var readerP = document.createElement('p');
    readerP.className = 'search-vbd-reader-link';
    var readerA = document.createElement('a');
    readerA.href = buildReaderUrl(verse.ref);
    readerA.className = 'tdb-dig-deeper__plan-link';
    readerA.textContent = 'Open the full chapter \u2192';
    readerA.setAttribute('aria-label', 'Open full chapter for ' + verse.ref);
    readerP.appendChild(readerA);
    digDeep.appendChild(readerP);
  }

  var crossSection =
    typeof vbStd.createDigDeeperCrossSection === 'function' ? vbStd.createDigDeeperCrossSection() : null;
  var planSection =
    typeof vbStd.createDigDeeperLinkSection === 'function'
      ? vbStd.createDigDeeperLinkSection('tdb-dig-deeper__plan', 'tdb-dig-deeper__plan-link')
      : null;

  digContent.appendChild(digDeep);
  if (crossSection && crossSection.wrap) digContent.appendChild(crossSection.wrap);
  if (planSection && planSection.wrap) digContent.appendChild(planSection.wrap);
  digDet.appendChild(digContent);

  vbStd.hydrateAskTheTeacherDigDeeper({ ref: verse.ref, text: verseText }, {
    detailsEl: digDet,
    deepRoot: digDeep,
    crossWrap: crossSection ? crossSection.wrap : null,
    crossListEl: crossSection ? crossSection.list : null,
    planWrap: planSection ? planSection.wrap : null,
    planLinkEl: planSection ? planSection.link : null
  });

  return digDet;
}

function buildHomeSearchGuideLine(planMatches, resourceMatches) {
  var lines = [
    'Verses first. Each card keeps plain help, one small step, a prayer, and more from the Word in the open.'
  ];
  if (planMatches && planMatches.length) {
    lines.push('If this battle needs more than one day, start with the first Battle Plan below.');
  } else if (resourceMatches && resourceMatches.length) {
    lines.push('If you need a quieter side door, use one of the related topic pages below.');
  }
  return lines.join(' ');
}

function buildHomeSearchRelatedAnglesSection(activeTopics, queryText) {
  var normalizedQuery = getHomeAskTheWordKey(queryText);
  var seen = Object.create(null);
  var options = [];
  (activeTopics || []).forEach(function (topic) {
    var normalized = normalizeInput(topic);
    if (!normalized || normalized === normalizedQuery || seen[normalized]) return;
    seen[normalized] = true;
    options.push(normalized);
  });
  if (!options.length) return null;

  var section = document.createElement('section');
  section.className = 'home-search-section';

  var heading = document.createElement('h3');
  heading.className = 'home-search-section-heading';
  heading.textContent = 'Also try these angles';
  section.appendChild(heading);

  var note = document.createElement('p');
  note.className = 'home-search-note';
  note.textContent = 'Shorter angles often sharpen the verses and the plan fit.';
  section.appendChild(note);

  var chips = document.createElement('div');
  chips.className = 'home-search-filter-row';
  options.slice(0, 4).forEach(function (topic) {
    var chip = document.createElement('button');
    chip.type = 'button';
    chip.className = 'home-search-filter-chip home-search-filter-chip--topic';
    chip.textContent = titleCaseHomeTopic(topic);
    chip.setAttribute('aria-label', 'Search for ' + titleCaseHomeTopic(topic));
    chip.addEventListener('click', function () {
      if (typeof window.runSearchWithInput === 'function') window.runSearchWithInput(topic);
    });
    chips.appendChild(chip);
  });
  section.appendChild(chips);

  return section;
}

/**
 * Part A — Crisis help (safety first).
 * Direct high-risk language only. Soft despair ("hopeless", "can't go on") does NOT force this block.
 * Returns { active: boolean, variant: 'self'|'others'|null }.
 */
function detectCrisisIntent(queryText) {
  var raw = String(queryText || '');
  if (!raw.trim()) return { active: false, variant: null };
  var norm = typeof normalizeInput === 'function'
    ? normalizeInput(raw)
    : raw.toLowerCase().replace(/['\u2019]/g, "'").replace(/\s+/g, ' ').trim();
  if (!norm) return { active: false, variant: null };

  // Harm to others: first-person / clear intent only (avoid Bible-history false positives).
  var othersRe = /\b(i want to (hurt|harm|kill) (someone|somebody|them|him|her|my)\b|i('m| am) going to (hurt|harm|kill) (someone|somebody|him|her|my)\b)/;
  if (othersRe.test(norm)) {
    return { active: true, variant: 'others' };
  }

  // Self-harm / suicidal despair — direct crisis language only.
  // Note: bare "suicide" alone is NOT enough (avoids grief/Q&A false positives).
  var selfRe = /\b(i want to die|i wanna die|want to kill myself|kill myself|killing myself|end my life|end it all|ending it all|better off dead|(dont|don't) want to (live|be alive)|wish i (was|were) dead|suicidal|(thinking about|considering|commit) suicide|self[-\s]?harm|hurt(ing)? myself|cut(ting)? myself|i keep cutting|i want to hurt myself)\b/;
  if (selfRe.test(norm)) {
    return { active: true, variant: 'self' };
  }

  return { active: false, variant: null };
}

/**
 * Build a DOM-safe crisis help block. Always intended to render above other search results.
 * @param {'self'|'others'} variant
 * @param {boolean} [compact]
 * @returns {HTMLElement|null}
 */
function buildCrisisHelpSection(variant, compact) {
  var kind = variant === 'others' ? 'others' : 'self';
  var section = document.createElement('section');
  section.className = compact
    ? 'tdb-crisis-block tdb-crisis-block--compact'
    : 'tdb-crisis-block';
  section.classList.add(kind === 'others' ? 'tdb-crisis-block--others' : 'tdb-crisis-block--self');
  section.setAttribute('role', 'alert');
  section.setAttribute('aria-label', 'Crisis help');
  section.setAttribute('data-tdb-crisis-variant', kind);

  var eyebrow = document.createElement('p');
  eyebrow.className = 'tdb-crisis-block__eyebrow';
  eyebrow.textContent = 'Crisis help';
  section.appendChild(eyebrow);

  var title = document.createElement('h2');
  title.className = 'tdb-crisis-block__title';
  title.textContent = kind === 'others' ? 'Get help right away' : 'Help is available now';
  section.appendChild(title);

  var lead = document.createElement('p');
  lead.className = 'tdb-crisis-block__lead';
  lead.textContent = kind === 'others'
    ? 'If you are thinking about hurting someone else, please get help now.'
    : 'You are not alone. If you are in crisis right now, please reach out for help.';
  section.appendChild(lead);

  var actions = document.createElement('ul');
  actions.className = 'tdb-crisis-block__actions';

  function addAction(href, linkClass, linkText, hintText, external) {
    var li = document.createElement('li');
    li.className = 'tdb-crisis-block__action';
    var a = document.createElement('a');
    a.className = linkClass;
    a.href = href;
    a.textContent = linkText;
    if (external) {
      a.target = '_blank';
      a.rel = 'noopener noreferrer';
    }
    li.appendChild(a);
    if (hintText) {
      var hint = document.createElement('span');
      hint.className = 'tdb-crisis-block__hint';
      hint.textContent = hintText;
      li.appendChild(hint);
    }
    actions.appendChild(li);
  }

  if (kind === 'others') {
    addAction('tel:911', 'tdb-crisis-block__primary', 'Call 911', 'If anyone is in immediate danger (U.S.)', false);
    addAction('tel:988', 'tdb-crisis-block__secondary', 'Call or text 988', 'U.S. Suicide & Crisis Lifeline', false);
  } else {
    addAction('tel:988', 'tdb-crisis-block__primary', 'Call or text 988', 'U.S. Suicide & Crisis Lifeline (24/7)', false);
    addAction('tel:911', 'tdb-crisis-block__secondary', 'Call 911', 'If you are in immediate danger (U.S.)', false);
  }
  addAction(
    'https://www.iasp.info/suicidalthoughts/',
    'tdb-crisis-block__link',
    'Find local help outside the U.S.',
    null,
    true
  );
  section.appendChild(actions);

  var note = document.createElement('p');
  note.className = 'tdb-crisis-block__note';
  note.textContent = kind === 'others'
    ? 'This site is not a substitute for emergency services.'
    : 'This site offers Scripture and quiet company. It is not a substitute for emergency or professional care.';
  section.appendChild(note);

  var whisper = document.createElement('p');
  whisper.className = 'tdb-crisis-block__whisper';
  whisper.textContent = 'God is near the brokenhearted \u2014 and reaching for help is wisdom, not weakness.';
  section.appendChild(whisper);

  try {
    if (typeof trackEvent === 'function') {
      trackEvent('crisis_block_shown', { variant: kind });
    }
  } catch (e) { /* never block help UI on analytics */ }

  return section;
}

/**
 * Insert crisis help at the top of a results host when high-risk language is detected.
 * Returns the crisis intent object (always), whether or not a node was inserted.
 */
function prependCrisisHelpIfNeeded(host, queryText, compact) {
  var intent = detectCrisisIntent(queryText);
  if (!intent || !intent.active || !host) return intent || { active: false, variant: null };
  if (host.querySelector && host.querySelector('.tdb-crisis-block')) return intent;
  var block = buildCrisisHelpSection(intent.variant, !!compact);
  if (!block) return intent;
  if (host.firstChild) host.insertBefore(block, host.firstChild);
  else host.appendChild(block);
  return intent;
}

/**
 * Force-show the self crisis block (used when suicidal-despair or self-harm matches).
 * Never skip this for those pastoral answers.
 */
function ensureCrisisHelpForSelfCrisis(host, compact) {
  if (!host) return;
  if (host.querySelector && host.querySelector('.tdb-crisis-block')) return;
  var block = buildCrisisHelpSection('self', !!compact);
  if (!block) return;
  if (host.firstChild) host.insertBefore(block, host.firstChild);
  else host.appendChild(block);
}

/** @deprecated Use ensureCrisisHelpForSelfCrisis */
function ensureCrisisHelpForSuicidalDespair(host, compact) {
  ensureCrisisHelpForSelfCrisis(host, compact);
}

